insert into public.preguntas (curso, tema, pregunta, opciones, correcta, explicacion, inventada) values
('PIR 18', 'Pregunta 1', 'Para conseguir un condicionamiento del miedo mediante la técnica de respuesta emocional condicionada (o supresión condicionada), una vez adquirida una respuesta instrumental:', '["Se aplica un estímulo discriminativo tras la respuesta.", "Se presentan secuencias de estímulo condicionado seguido de estímulo incondicionado aversivo (p. ej. una descarga), todo ello mientras dura la tarea instrumental.", "Basta con suprimir el reforzador, provocando miedo a perderlo realizando esa respuesta.", "Se mide directamente con número de estímulos condicionados e incondicionados emparejados."]'::jsonb, 1, null, false),
('PIR 18', 'Pregunta 2', 'Una de las siguientes afirmaciones es INCORRECTA respecto a los efectos de los programas de refuerzo simples:', '["Los programas de razón generan tasas más altas que los de intervalo (en condiciones equiparables).", "Los programas fijos suelen generar pausas después de los refuerzos.", "Los programas variables no muestran pausas postrefuerzo y además generan tasas de respuestas superior a los fijos.", "Cuanto más baja es la razón o el intervalo del refuerzo, mayor resistencia a la extinción."]'::jsonb, 3, null, false),
('PIR 18', 'Pregunta 3', 'Señale cuál de las siguientes situaciones se explica, de manera más ajustada, con el principio de Premack:', '["El niño que hace una tarea porque después recibe un elogio.", "Niños que hacen los deberes pronto en casa y así pueden jugar con los videojuegos.", "Recibir una multa por conducir con exceso de velocidad.", "Recibir el sueldo mensual después de cumplir con el horario de trabajo en ese mes."]'::jsonb, 1, null, false),
('PIR 18', 'Pregunta 4', 'En el contexto del reconocimiento oral de palabras, el concepto y fenómeno denominado "punto de unicidad" hace referencia a:', '["Una variable determinante de los tiempos de reconocimiento de las palabras habladas.", "Al fenómeno por el que las palabras más frecuentes se reconocen más rápido que las que son de menor frecuencia.", "Al fenómeno por el que las palabras que se aprenden antes en la vida se reconocen más lento que las que se aprenden más tarde.", "Al hecho de que el contexto oracional y discursivo sirve para acelerar el reconocimiento de las palabras que son predecibles."]'::jsonb, 0, null, false),
('PIR 18', 'Pregunta 5', 'En la teoría neurocientífica de la atención: ¿qué tres redes neuronales atencionales propuso Michael Posner?:', '["La red de control ejecutivo, la red atencional anterior y la red de vigilancia.", "La red de orientación, la red atencional posterior y la red de vigilancia.", "La red de alerta, la red de orientación y la red de control ejecutivo.", "La red de alerta, la red de control ejecutivo y la red atencional anterior."]'::jsonb, 2, null, false),
('PIR 18', 'Pregunta 6', 'Si pedimos a alguien que describa un viaje que realizó a Roma hace cinco años, para esa persona el recuerdo será más fácil si este viaje es el único que ha realizado en su vida que si realiza viajes similares todos los años. De acuerdo con la psicología de la memoria ¿qué nos permite explicar este hecho?:', '["El principio de sobrecarga de la clave.", "La teoría de los niveles de procesamiento.", "El principio de la especificidad de la codificación.", "La teoría del decaimiento de la huella."]'::jsonb, 0, null, false),
('PIR 18', 'Pregunta 7', 'Según la hipótesis de los niveles de procesamiento de Craik y Lockhart ¿de qué depende nuestra capacidad para recuperar una determinada información de la memoria episódica?:', '["Del tiempo que se mantuvo esa información en la memoria a corto plazo mediante repaso de mantenimiento.", "De la profundidad del procesamiento de esa información durante la codificación.", "Del tipo de clave de recuperación utilizada como punto de partida de los procesos de búsqueda en la memoria.", "De la similitud existente entre el contenido que se quiere recuperar y otros contenidos disponibles en la memoria."]'::jsonb, 1, null, false),
('PIR 18', 'Pregunta 8', 'Cuando en un experimento de estimación de magnitudes hay que aumentar mucho más que el doble la intensidad física del estímulo para doblar la sensación que produce, hablamos de un fenómeno denominado:', '["Expansión de respuesta.", "Compresión de respuesta.", "Respuesta paradójica.", "Potencial de respuesta."]'::jsonb, 1, null, false),
('PIR 18', 'Pregunta 9', 'Los sonidos de frecuencias más bajas producen una mayor respuesta de los receptores situados en la zona de la membrana basilar situada:', '["Más cerca del extremo de la espiral de la cóclea (ápice).", "Más cerca de la base de la membrana (ventana oval).", "Entre la ventana oval y la zona intermedia.", "Entre el ápice y la zona intermedia."]'::jsonb, 0, null, false),
('PIR 18', 'Pregunta 10', 'Señala cuál de los siguientes fenómenos resultan explicados por la actividad de las células oponentes:', '["Las Bandas de Mach.", "Los resultados de los experimentos de igualación de colores.", "La experiencia de las post-imágenes de color.", "La Parrilla de Hermann."]'::jsonb, 2, null, false),
('PIR 18', 'Pregunta 11', 'Las células madre neurales pueden generar nuevas neuronas y se localizan en:', '["Hipotálamo, subtálamo y adenohipófisis.", "Zona subventricular, hipocampo y bulbo olfatorio.", "Troncoencéfalo, cerebelo y bulbo raquídeo.", "Nervio vago, hipogloso y glosofaríngeo."]'::jsonb, 1, null, false),
('PIR 18', 'Pregunta 12', 'La asterognosia se define como:', '["La pérdida del conocimiento o del sentido del propio cuerpo.", "La incapacidad para reconocer objetos a través del tacto.", "La incapacidad para localizar y denominar partes del propio cuerpo.", "Un tipo de agnosia digital."]'::jsonb, 1, null, false),
('PIR 18', 'Pregunta 13', 'Las "neuronas de von Economo" en humanos:', '["Se localizan en cerebelo y tálamo y son claves para el equilibrio.", "Están relacionadas con el sistema de neuronas de lugar (place neurons).", "Se localizan en el hipocampo y se relacionan con las respuestas emocionales.", "Se localizan en la ínsula, cíngulo anterior y corteza prefrontal dorsolateral y se relacionan con la aparición de la teoría de la mente."]'::jsonb, 3, null, false),
('PIR 18', 'Pregunta 14', 'El Proyecto Conectoma humano se basa:', '["En el estudio de la conectividad cerebral en reposo mediante la técnica de Resonancia Magnética Funcional (RMf).", "En el estudio de la conectividad cerebral tras presentar estímulos mediante la técnica de la Resonancia Magnética (RM).", "En el análisis de las conexiones desde la corteza cerebral a la médula espinal usando la técnica de la Electroencefalografía.", "En el análisis de las conexiones interhemisféricas mediante el uso de la técnica de la Magnetoencefalografía."]'::jsonb, 0, null, false),
('PIR 18', 'Pregunta 15', 'En la afasia de conducción destaca la dificultad del paciente para:', '["Repetir palabras o frases.", "Articular palabras (anartria).", "Comprender el lenguaje.", "Nombrar objetos (denominación)."]'::jsonb, 0, null, false),
('PIR 18', 'Pregunta 16', 'Los campos oculares frontales son zonas corticales encargadas de la dirección de la mirada voluntaria y se localizan en:', '["La corteza premotora.", "La corteza occipital.", "La corteza parietal.", "Los colículos superiores"]'::jsonb, 0, null, false),
('PIR 18', 'Pregunta 17', 'El asta de Ammon y el giro dentado son estructuras celulares que forman parte de la anatomía del:', '["Hipotálamo.", "Hipocampo.", "Giro retrosplenial.", "Cerebelo."]'::jsonb, 1, null, false),
('PIR 18', 'Pregunta 18', 'Un escotoma es:', '["Una pérdida de visión en una cuarta parte del campo visual.", "Una pérdida de visión en la mitad de un campo visual.", "Un pequeño punto ciego producido por una pequeña lesión cerebral occipital.", "Una gran mácula (mancha) en el centro del campo visual por una lesión cerebral occipital."]'::jsonb, 2, null, false),
('PIR 18', 'Pregunta 19', 'La agnosia de las marcas topográficas se define como:', '["Una incapacidad para utilizar las características sobresalientes del entorno para orientarse.", "Una distorsión espacial de la ubicación de su propio cuerpo respecto del espacio externo.", "Una incapacidad para aprender nuevos itinerarios.", "Un déficit para reconocer las partes de su propio cuerpo."]'::jsonb, 0, null, false),
('PIR 18', 'Pregunta 20', 'La ataxia óptica es un síntoma frecuente en lesiones cerebrales parietales posteriores uni o bilaterales que se caracteriza por:', '["Un déficit para alcanzar objetos bajo guía visual.", "Una marcha desordenada (ebria).", "Temblores de las extremidades al enfocar un objeto.", "Ser la única manifestación clínica del Síndrome de Bálint."]'::jsonb, 0, null, false),
('PIR 18', 'Pregunta 21', 'Un bebé que ha desarrollado un apego evasivo, cuando su cuidador se ausenta mientras está jugando, suele reaccionar de la siguiente manera:', '["Detiene su juego y no está feliz.", "Se asusta mucho.", "Grita y llora.", "Continúa jugando."]'::jsonb, 3, null, false),
('PIR 18', 'Pregunta 22', '¿Cuál de las siguientes competencias cognitivas sufre menos declive durante el proceso de envejecimiento?:', '["La inteligencia fluida.", "La inteligencia cristalizada.", "La velocidad cognitiva.", "La atención dividida."]'::jsonb, 1, null, false),
('PIR 18', 'Pregunta 23', 'María, de dos años y medio, utiliza la palabra ''coche'' para designar no sólo a los coches, sino a todos objetos que tienen ruedas (trenes, motos, etc.) ¿cómo se denomina este fenómeno?:', '["Condensación léxica.", "Holofrase.", "Sobreextensión.", "Palabra con significado centrífugo."]'::jsonb, 2, null, false),
('PIR 18', 'Pregunta 24', 'De acuerdo con Erikson, los adultos jóvenes típicamente se encuentran ante el dilema de comprometerse y establecer relaciones estrechas mutuamente satisfactorias con otras personas sin perder la propia identidad ¿cómo se denomina este dilema?:', '["Generatividad frente a estancamiento.", "Integridad frente a desesperación.", "Compromiso viral frente a desimplicación vital.", "Intimidad frente a aislamiento."]'::jsonb, 3, null, false),
('PIR 18', 'Pregunta 25', 'Algunos adolescentes se comprometen con trayectorias de desarrollo de manera prematura, sin haber sopesado y explorado alternativas (p.e. escogen una carrera porque es la que sus padres desean) ¿en qué estado de identidad se encuentran?:', '["Difusión.", "Logro.", "Moratoria.", "Exclusión."]'::jsonb, 3, null, false),
('PIR 18', 'Pregunta 26', 'La permanencia del objeto es uno de los grandes logros cognitivos de la infancia. De acuerdo con Piaget ¿en qué momento queda establecida por completo?:', '["Hacia el final de la etapa sensoriomotora.", "Al desaparecer los reflejos innatos.", "Cuando se supera el egocentrismo infantil.", "Alrededor de los cinco años."]'::jsonb, 0, null, false),
('PIR 18', 'Pregunta 27', '¿Cuál de los siguientes NO es un síntoma del llamado "Pensamiento grupal" (Janis)?:', '["Sobreestimación del propio grupo.", "Mentalidad cerrada.", "Divergencia opositora.", "Incremento en la presión de conformidad."]'::jsonb, 2, null, false),
('PIR 18', 'Pregunta 28', 'La denominada "Teoría del conflicto de grupo realista" señala que la causa fundamental de los conflictos humanos es:', '["La existencia de prejuicios.", "Los instintos agresivos.", "Los valores transmitidos socialmente.", "La competencia por recursos limitados."]'::jsonb, 3, null, false),
('PIR 18', 'Pregunta 29', 'Cuando un sujeto desarrolla un patrón de atribución en el que considera que las víctimas son responsables de sus propias desgracias, está desarrollando la llamada:', '["Creencia en un mundo justo.", "Reciprocidad.", "Profecía autocumplida.", "Atribución externa."]'::jsonb, 0, null, false),
('PIR 18', 'Pregunta 30', 'El proceso cognitivo que tiende a atribuir las conductas de los otros a causas internas más que a causas situacionales se denomina:', '["Mezquindad cognitiva.", "Sesgo optimista.", "Error fundamental de atribución.", "Heurístico de representatividad."]'::jsonb, 2, null, false),
('PIR 18', 'Pregunta 31', 'La técnica de persuasión consiste en lanzar una pequeña petición con el objeto de que se acceda posteriormente a una petición mayor se denomina:', '["Técnica de la bola baja.", "Técnica del pie en la puerta.", "Técnica del portazo en la cara.", "Técnica de reciprocidad."]'::jsonb, 1, null, false),
('PIR 18', 'Pregunta 32', 'En relación con los diseños factoriales, indique por favor la afirmación CORRECTA:', '["Una de las ventajas del diseño factorial en comparación con el diseño multigrupos es que permite examinar los efectos de interacción entre las variables independientes y las variables dependientes.", "En los diseños factoriales, cuando la interacción es estadísticamente significativa, los efectos principales no son consistentes y se aconseja interpretar los efectos simples.", "Los resultados obtenidos mediante un diseño factorial aleatorio, pueden analizarse tanto mediante análisis factorial de la varianza como mediante análisis factorial de componentes principales.", "Los diseños factoriales de medidas parcialmente repetidas se caracterizan por la utilización de dos o más variables dependientes."]'::jsonb, 1, null, false),
('PIR 18', 'Pregunta 33', 'En el ámbito de los diseños de investigación, indique la afirmación CORRECTA:', '["El diseño con grupo de control no equivalente es un diseño experimental prototípico.", "Los diseños de series temporales interrumpidas se caracterizan por el registro de múltiples medidas antes y después de introducir la intervención o el tratamiento.", "En los diseños cuasiexperimentales de grupo único la regla de asignación utilizada es no aleatoria pero conocida.", "Los diseños de discontinuidad en la regresión se definen por la utilización de una variable de asignación no aleatoria ni conocida."]'::jsonb, 1, null, false),
('PIR 18', 'Pregunta 34', 'En lo que respecta a la validez interna del diseño, indique cuál de las siguientes afirmaciones es INCORRECTA:', '["En los diseños de medidas repetidas, las amenazas a la validez interna provienen de los efectos de orden y residuales.", "Los efectos de orden y residuales pueden ser controlados mediante técnicas de eliminación.", "En los diseños N=1 se utilizan técnicas de control como la equiponderación.", "En los diseños intersujeto, la equivalencia inicial de los grupos se garantiza utilizando la regla de asignación aleatoria."]'::jsonb, 1, null, false),
('PIR 18', 'Pregunta 35', 'Con relación a los supuestos del modelo estadístico, indique la afirmación CORRECTA:', '["La normalidad es un supuesto que puede ser explorado mediante la prueba de Brown-Forsythe.", "La homogeneidad de la varianza es un supuesto cuya comprobación suele realizarse mediante la prueba W de Welch.", "La prueba de Durbin-Watson analiza la existencia de autocorrelación entre residuales y nos informa acerca del supuesto de independencia de las observaciones.", "Un valor en la prueba de Shapiro-Wilks de SW=2,781; p=0,05 muestra un valor estadísticamente significativo que indica que se cumple el supuesto de normalidad."]'::jsonb, 2, null, false),
('PIR 18', 'Pregunta 36', 'En el ámbito de la validez de conclusión estadística, indique la afirmación INCORRECTA:', '["La baja potencia estadística puede implicar un alto riesgo de cometer un error de tipo II.", "La escasa fiabilidad de las medidas utilizadas puede influir en las conclusiones sobre covariación.", "Existen estadísticos que de manera sistemática infraestiman o sobreestiman la magnitud de un efecto, lo cual amenaza la validez de la conclusión estadística.", "La heterogeneidad de las unidades muestrales incrementa la probabilidad de detectar el efecto objeto de estudio."]'::jsonb, 3, null, false),
('PIR 18', 'Pregunta 37', 'En el modelo de regresión lineal simple cuando trabajamos en puntuaciones típicas, el coeficiente de regresión (beta) de la variable independiente (VI) es igual a:', '["La varianza de la variable dependiente (VD)", "0.", "La correlación de Pearson entre la VD y la VI.", "1."]'::jsonb, 2, null, false),
('PIR 18', 'Pregunta 38', 'Antes de aplicar una prueba t de diferencias de medias para grupos independientes, hay que comprobar el supuesto de homocedasticidad ¿Cuál de las siguientes pruebas se emplea para tal fin?:', '["Brown-Forsythe.", "U de Mann-Witney.", "Chi-cuadrado.", "F de Levene."]'::jsonb, 3, null, false),
('PIR 18', 'Pregunta 39', 'La fórmula de Spearman-Brown se usa para estimar el cambio que se produciría en el coeficiente de fiabilidad de un test cuando aumentamos:', '["La variabilidad de la muestra.", "La longitud, añadiendo ítems paralelos.", "El tamaño de la muestra.", "El tiempo transcurrido entre dos aplicaciones de test."]'::jsonb, 1, null, false),
('PIR 18', 'Pregunta 40', 'En el contexto de los diseños experimentales, es necesario utilizar alguna(s) de las siguientes estrategias de control para garantizar la validez interna. Indique la opción INCORRECTA:', '["Técnicas de equilibración como la asignación aleatoria.", "Selección aleatoria de la muestra.", "Técnicas de constancia, utilizando un único valor de la variable perturbadora en todos los grupos.", "Equiponderación en el caso de diseños experimentales con medidas repetidas."]'::jsonb, 1, null, false),
('PIR 18', 'Pregunta 41', 'En el ámbito de la metodología observacional, señale la afirmación INCORRECTA:', '["El método observacional se caracteriza por la no intervención del investigador en el fenómeno de estudio y por la no restricción de las respuestas de los sujetos a través de las tareas o los instrumentos de evaluación.", "En la metodología observacional, el sistema de categorías puede considerarse el instrumento de medida.", "El método observacional se caracteriza por la búsqueda de relaciones causales y el control del comportamiento de los sujetos.", "En los diseños observacionales, para calcular la fiabilidad inter-observadores se puede utilizar el índice de Kappa."]'::jsonb, 2, null, false),
('PIR 18', 'Pregunta 42', '¿Qué caracteriza a los sujetos con "ansiedad defensiva" baja o represores?:', '["Se describen como calmados pero muestran niveles altos de excitabilidad autonómica en situaciones de estrés.", "Se describen como calmados y muestran niveles bajos de excitabilidad autonómica en situaciones de estrés.", "Se describen como ansiosos, pero muestran niveles bajos de excitabilidad autonómica en situaciones de estrés.", "Se describen como ansiosos y muestran niveles altos de excitabilidad autonómica en situaciones de estrés."]'::jsonb, 0, null, false),
('PIR 18', 'Pregunta 43', '¿A qué hace referencia el concepto de expectativa de autoeficacia (Bandura) en Psicología de la Personalidad?:', '["La capacidad percibida de hacer frente a cualquier situación.", "La capacidad percibida de hacer frente a situaciones específicas.", "Las expectativas de obtención de refuerzo.", "Lo que la gente desea que suceda."]'::jsonb, 1, null, false),
('PIR 18', 'Pregunta 44', 'Atendiendo a la teoría de la sensibilidad al refuerzo de Gray, las recompensas:', '["Tienen un mayor impacto emocional en los extrovertidos que en los introvertidos.", "Tienen un mayor impacto emocional en los introvertidos que en los extrovertidos.", "Tienen el mismo impacto emocional tanto en introvertidos como en extravertidos.", "El impacto diferencial entre los introvertidos y extravertidos está mediado por el autoconcepto."]'::jsonb, 0, null, false),
('PIR 18', 'Pregunta 45', 'Las teorías del rasgo en psicología de la personalidad se han desarrollado utilizando, fundamentalmente:', '["Un enfoque ideográfico.", "Una metodología cualitativa.", "Una metodología experimental.", "Una metodología correlacional."]'::jsonb, 3, null, false),
('PIR 18', 'Pregunta 46', '¿Cómo se denomina, en Psicología de la Personalidad, el enfoque que busca identificar dimensiones de personalidad que puedan ser cuantificadas y las utiliza para comparar grupos de individuos?:', '["Enfoque ideográfico.", "Enfoque nomotético.", "Enfoque experimental.", "Enfoque clínico."]'::jsonb, 1, null, false),
('PIR 18', 'Pregunta 47', '¿Cuál sería la definición más apropiada de talento?:', '["Una puntuación de CI situada al menos dos desviaciones típicas por encima de la media de la población.", "Una habilidad especial muy desarrollada.", "Un altísimo nivel de creatividad.", "Una habilidad y destreza muy superior durante el período de la infancia."]'::jsonb, 1, null, false),
('PIR 18', 'Pregunta 48', 'Indique cuál de las siguientes afirmaciones respecto a la reactancia psicológica es FALSA (Brehm):', '["La reactancia se activa cuando uno se siente libre y capaz para ejecutar una determinada conducta y percibe una amenaza a su libertad de acción.", "La cantidad de reactancia experimentada está en función, entre otros factores, de la importancia de la conducta amenazada, de la extensión de la amenaza y de la legitimidad del agente amenazador.", "La amenaza externa impersonal tiene más fuerza que la amenaza personal, provocando una mayor intensidad de la reactancia.", "La reactancia psicológica se puede producir también de forma \"vicaria\": cuando no es directamente amenazada la libertad de una persona, pero sí la de alguien próximo."]'::jsonb, 2, null, false),
('PIR 18', 'Pregunta 49', '¿Cuál sería la combinación más característica de los individuos impulsivos según el modelo de Gray?:', '["Alta extraversión y alto neuroticismo (alta inestabilidad emocional).", "Alta extraversión y bajo neuroticismo (baja inestabilidad emocional).", "Alta introversión y alto neuroticismo (alta inestabilidad emocional).", "Alta introversión y bajo neuroticismo (baja estabilidad emocional)."]'::jsonb, 0, null, false),
('PIR 18', 'Pregunta 50', '¿Qué capacidad intelectual permite evaluar, con mayor nivel de precisión, el Test Libre de Cultura de R. B. Cattell (Cattell Culture-Fair Test)?:', '["Gr (fluidez/recuerdo).", "Gs (velocidad cognitiva).", "Gf (inteligencia fluida).", "Gc (inteligencia cristalizada)."]'::jsonb, 2, null, false),
('PIR 18', 'Pregunta 51', '¿Cuál de los siguientes enunciados expresa correctamente la diferencia entre influencias hereditarias (h), innatas (i) y congénitas (c)?:', '["Las h se producen por mutaciones genéticas, las i se asocian los genes que proceden de los progenitores y las c se atribuyen a factores intrauterinos.", "Las h se atribuyen a los factores intrauterinos, las i se producen por mutaciones genéticas y las c se asocian a los genes que proceden de los progenitores.", "Las h se asocian a los genes que proceden de los progenitores, las i se atribuyen a los factores intrauterinos y las c se producen por mutaciones genéticas.", "Las h se asocian a los genes que proceden de los progenitores, las i se producen por mutaciones genéticas y las c se atribuyen a los factores intrauterinos."]'::jsonb, 3, null, false),
('PIR 18', 'Pregunta 52', '¿Cuál es el efecto del fenómeno conocido como "restricción de rango" sobre el valor de correlación observado entre dos variables psicológicas:', '["El aumento de ese valor.", "La disminución de ese valor.", "La desaparición de ese valor.", "El cambio de signo de ese valor."]'::jsonb, 1, null, false),
('PIR 18', 'Pregunta 53', '¿Cuál sería la puntuación z que correspondería a un CI de 130 en la batería Wechsler?:', '["+1.0.", "+2.0.", "+3.0.", "+4.0."]'::jsonb, 1, null, false),
('PIR 18', 'Pregunta 54', '¿Qué cinco características de personalidad postula el modelo de los Cinco Grandes como dimensiones básicas de personalidad?:', '["Extraversión, Surgencia, Neuroticismo, Motivación de Logro y Apertura a la Experiencia.", "Extraversión, Exvia, Neuroticismo, Motivación de Logro y Apertura a la Experiencia.", "Extraversión, Neuroticismo, Amabilidad, Responsabilidad y Apertura a la Experiencia.", "Extraversión, Ansiedad, Amabilidad, Escrupulosidad y Responsabilidad."]'::jsonb, 2, null, false),
('PIR 18', 'Pregunta 55', 'El "test del dibujo del árbol" es una técnica proyectiva:', '["Estructural.", "Temática.", "Expresiva.", "Constructiva."]'::jsonb, 2, null, false),
('PIR 18', 'Pregunta 56', 'Cuando el coeficiente de fiabilidad de un test se calcula en una muestra muy homogénea de sujetos su valor:', '["Aumenta.", "Disminuye.", "Se iguala al coeficiente de validez.", "Es independiente de la homogeneidad de la muestra."]'::jsonb, 1, null, false),
('PIR 18', 'Pregunta 57', 'Al proceso de desarrollar una conversión del sistema de unidades de un test al sistema de unidades de otro se denomina:', '["Calibración.", "Equiparación.", "Baremación.", "Sustitución."]'::jsonb, 1, null, false),
('PIR 18', 'Pregunta 58', '¿Qué evalúa el test de carga de agua en la enuresis funcional?:', '["Capacidad funcional media de la vejiga.", "Capacidad funcional mínima de la vejiga.", "Capacidad funcional máxima de la vejiga.", "Capacidad funcional residual de la vejiga."]'::jsonb, 2, null, false),
('PIR 18', 'Pregunta 59', '¿Qué mide el Test de "emparejamiento de figuras conocidas" de Caims y Cammock en el trastorno por déficit de atención e hiperactividad?:', '["Reflexibilidad-impulsividad.", "Inatención.", "Incontrolabilidad motora.", "Vigilancia."]'::jsonb, 0, null, false),
('PIR 18', 'Pregunta 60', 'Señale cuál de las siguientes pruebas evalúa las habilidades previas a la lectura:', '["Batería de procesos lectores (PROLEC).", "Test de análisis de la lectura y la escritura (TALE).", "Test Reversal.", "Exploración de las dificultades individuales de la lectura (EDIL)."]'::jsonb, 2, null, false),
('PIR 18', 'Pregunta 61', '¿Qué escala del WISC-V se considera "secundaria"?:', '["No verbal.", "Comprensión verbal.", "Visoespacial.", "Razonamiento fluido."]'::jsonb, 0, null, false),
('PIR 18', 'Pregunta 62', '¿Qué afirmación es correcta respecto de la Escala Bayley de Desarrollo Infantil (BSID)?:', '["Es aplicable a niños de hasta 3 años y medio.", "Entre otros aspectos, será necesaria la observación y juicio cualitativo del observador.", "No contempla el desarrollo psicomotriz.", "El tiempo de aplicación no debe sobrepasar los 45 min."]'::jsonb, 1, null, false),
('PIR 18', 'Pregunta 63', '¿Qué tarea debe realizar una niña a la que se le administra el test de Apercepción Temática?:', '["Narrar una historia.", "Asociar una respuesta a un estímulo.", "Organizar el material dado sobre la base de distintas consignas.", "Dibujar una figura."]'::jsonb, 0, null, false),
('PIR 18', 'Pregunta 64', '¿Qué afirmación es correcta con respecto de la aplicación del método sociométrico de las nominaciones en un aula?:', '["No se indaga el porqué de las nominaciones.", "Se obtienen los indicadores de elecciones y de rechazos.", "Se pide a los alumnos que puntúen a cada compañero en una escala de cinco puntos.", "Las nominaciones se analizan en función de los atributos interpersonales y no por el número de nominaciones."]'::jsonb, 1, null, false),
('PIR 18', 'Pregunta 65', 'En referencia a las técnicas de registro que podemos utilizar en la observación ¿qué caracteriza a las escalas de apreciación?:', '["Son técnicas de registro en las que los evaluadores realizan descripciones de lo observado, sin existir estructuración previa para la recogida de datos.", "Son técnicas que se usan para cuantificar, cualificar o clasificar las actividades de un sujeto según específicas definiciones conductuales, dimensiones o atributos de personalidad que se han establecido previamente.", "Sirven para evaluar las interacciones entre ambiente social y conducta, o las relaciones funcionales (antecedentes y consecuentes) que se producen en la interacción de dos o más sujetos.", "Son procedimientos de observación de conductas específicas situadas en unas coordenadas espacio-temporales, con el objetivo de analizar las relaciones entre conducta y ambiente."]'::jsonb, 1, null, false),
('PIR 18', 'Pregunta 66', 'Señale cuál de las siguientes afirmaciones NO es correcta respecto de las escalas McCarthy de Aptitudes y Psicomotricidad (MSCA):', '["Nos permiten obtener un Índice General Intelectual a partir de la puntuación de tres de sus escalas.", "Son útiles para evaluar niños con retraso intelectual.", "Constan de tres subescalas: de procesamiento mental simultáneo, procesamiento mental sucesivo y conocimientos académicos.", "Se originaron para la evaluación de niños muy pequeños y con dificultades de aprendizaje."]'::jsonb, 2, null, false),
('PIR 18', 'Pregunta 67', '¿Cuál de los siguientes tests de inteligencia NO posee un componente verbal y se considera con escaso peso de contenidos culturales o conocimientos?:', '["El OTIS Sencillo (OS).", "El Test de Matrices Progresivas de Raven.", "El K-ABC (Kaufman Assessment Battery for Children) de Kaufman.", "El IG-2 (Inteligencia General Nivel 2)."]'::jsonb, 1, null, false),
('PIR 18', 'Pregunta 68', '¿Cuáles son las técnicas proyectivas en las que el sujeto debe narrar una historia ante un material visual con distintos tipos de estructuración?:', '["Las técnicas expresivas.", "Las técnicas constructivas.", "Las técnicas asociativas.", "Las técnicas temáticas."]'::jsonb, 3, null, false),
('PIR 18', 'Pregunta 69', 'El Test del Pueblo es una técnica de evaluación proyectiva:', '["Constructiva.", "Temática.", "Asociativa.", "Expresiva."]'::jsonb, 0, null, false),
('PIR 18', 'Pregunta 70', 'Las fases del registro de las respuestas psicofisiológicas son (por orden):', '["Amplificación-Detección-Conversión-Transformación-Registro.", "Detección-Amplificación-Transformación-Conversión-Registro.", "Detección-Amplificación-Transformación-Registro-Conversión.", "Detección-Transformación-Amplificación-Registro-Conversión."]'::jsonb, 3, null, false),
('PIR 18', 'Pregunta 71', 'El test IG-2 (Inteligencia General Nivel 2) mide la inteligencia:', '["En personas intelectualmente superdotadas, preferentemente.", "En niños con capacidad media-alta preferentemente.", "Fluida.", "Cristalizada."]'::jsonb, 3, null, false),
('PIR 18', 'Pregunta 72', 'Una puntuación "eneatipo" en un test requiere la transformación:', '["De las puntuaciones en una escala que va del 1 al 99 con una media igual a 50.", "De las puntuaciones en una escala que va del 1 al 99 con una desviación típica igual a 10.", "De las puntuaciones en una escala que va del 1 al 9 con una desviación típica igual a 2.", "De las puntuaciones en una escala que va del 1 al 9 con una desviación típica igual a 5."]'::jsonb, 2, null, false),
('PIR 18', 'Pregunta 73', 'En la evaluación psicológica, la "objetividad del registro", en el sentido de que diferentes evaluadores obtengan resultados semejantes, hace referencia:', '["A la validez externa del test.", "A la validez interna del test.", "A la fiabilidad del test.", "A la consistencia interna del test."]'::jsonb, 2, null, false),
('PIR 18', 'Pregunta 74', 'Los principios de "adecuación" y "consentimiento con conocimiento" forman parte del código ético que debe respetar el evaluador y están, concretamente, destinados a:', '["La competencia y el rigor científico de su actuación.", "Crear un ambiente distendido en la consulta.", "Evitar incurrir en un exceso de intromisión en la vida privada del evaluado.", "Fomentar la validez de los instrumentos utilizados."]'::jsonb, 2, null, false),
('PIR 18', 'Pregunta 75', 'La Escala de Funcionamiento Cognitivo Global (DRS):', '["No resulta de utilidad para evaluar trastornos neurocognitivos, debido a que contiene más de 50 items.", "Incluye la medida del nivel de respuestas de activación psicofisiológica.", "Permite identificar el delirio y distinguirlo de los trastornos neurocognitivos.", "No es apta para la detección de déficits fronto-subcorticales."]'::jsonb, 2, null, false),
('PIR 18', 'Pregunta 76', 'La entrevista para el diagnóstico del autismo (ADI-R):', '["Es una entrevista estructurada.", "Es una entrevista centrada en la interacción social.", "Es factible utilizarla desde el primer año de vida.", "No requiere evaluación previa del CI."]'::jsonb, 0, null, false),
('PIR 18', 'Pregunta 77', 'La dificultad para articular fonemas, sílabas o palabras se denomina:', '["Disartria.", "Aprosodia.", "Corpolalia.", "Dislalia."]'::jsonb, 3, null, false),
('PIR 18', 'Pregunta 78', 'La logoclonía se refiere a:', '["La incapacidad para la entonación y musicalidad.", "Realizar tics fónicos complejos de carácter soez.", "Una repetición espasmódica de una sílaba en medio o al final de una palabra.", "La dificultad para realizar una frase con reglas gramaticales correctas."]'::jsonb, 2, null, false),
('PIR 18', 'Pregunta 79', 'Una mujer que cree que los periódicos contienen información encriptada que sólo ella conoce porque alguien importante le está mandando un mensaje desde Japón, se trata de una idea delirante:', '["Persecutoria.", "Metacognitiva.", "De referencia.", "De grandeza."]'::jsonb, 2, null, false),
('PIR 18', 'Pregunta 80', '¿Cuál de las siguientes afirmaciones es característica de un "delirium"?:', '["Es un trastorno del contenido del pensamiento.", "Algunos autores lo consideran un síntoma primario de esquizofrenia.", "Se suele acompañar de desorientación, respuestas emocionales intensas y alucinaciones.", "Puede presentarse en personas sanas en situaciones de fatiga extrema."]'::jsonb, 2, null, false),
('PIR 18', 'Pregunta 81', 'Una mujer nos informa de lo siguiente "Sé que suena muy raro y que no era real, pero después de la muerte de mi marido, durante algún tiempo, seguía oyendo sus silbidos por la casa". ¿Qué alteración podría estar describiendo?:', '["El fenómeno del doble.", "Una ilusión de Sosias.", "Una experiencia de desrealización.", "Una pseudoalucinación."]'::jsonb, 3, null, false),
('PIR 18', 'Pregunta 82', 'Un paciente diagnosticado de esquizofrenia experimenta una sensación molesta en la rodilla derecha cada vez que oye el canto de un pájaro, y está convencido de que dicho sonido es la causa del dolor que siente ¿De qué tipo de alucinación se trata?:', '["Alucinación refleja.", "Alucinación extracampina.", "Alucinación negativa.", "Autoscopia."]'::jsonb, 0, null, false),
('PIR 18', 'Pregunta 83', 'El engaño perceptivo en el que un estímulo externo que produjo la percepción inicial ya no se halla presente, se denomina:', '["Hipoalgesia.", "Pareidolia.", "Sinestesia.", "Imagen eidética."]'::jsonb, 3, null, false),
('PIR 18', 'Pregunta 84', 'Con relación a las pseudoalucinaciones, señale la opción correcta:', '["Suelen darse en las modalidades olfativas y táctil.", "Se acompañan de ausencia de la convicción de realidad por parte de la persona.", "Son imágenes mentales poco claras o con poca viveza.", "No suelen estar asociadas a estados hipnagógicos e hipnopómpicos."]'::jsonb, 1, null, false),
('PIR 18', 'Pregunta 85', 'En la alucinosis alcohólica se producen alucinaciones:', '["Gustativas y no visuales.", "Visuales y no auditivas.", "Auditivas, más elaboradas que las producidas en la depresión mayor.", "Auditivas, pero menos elaboradas que en la esquizofrenia."]'::jsonb, 3, null, false),
('PIR 18', 'Pregunta 86', 'La "aprosexia" es un término utilizado para designar:', '["El grado más intenso de distraibilidad y la ausencia completa de atención.", "La inestabilidad atencional.", "La incapacidad para adquirir nueva información prosémica.", "La dificultad para utilizar las relaciones gramaticales y sus reglas."]'::jsonb, 0, null, false),
('PIR 18', 'Pregunta 87', 'La dismegalopsia es un tipo de ilusión perceptiva en la que:', '["Se organiza y se da significado a un estímulo ambiguo y poco organizado.", "Se siente la presencia de otros objetos perceptivos (especialmente otras personas).", "Se ve alterada la percepción de la forma y el tamaño de los objetos.", "Está alterada la integración de la información proveniente de sentidos diferentes."]'::jsonb, 2, null, false),
('PIR 18', 'Pregunta 88', '¿Cómo se denomina la alteración en el lenguaje caracterizada por una dificultad para articular fonemas, sílabas y palabras?:', '["Disfasia.", "Anartria.", "Dislalia.", "Dislexia."]'::jsonb, 2, null, false),
('PIR 18', 'Pregunta 89', '¿En qué consiste el delirio de paramentos?:', '["Creencia de que personas, animales, materiales, radiación, sonidos o gases pueden pasar a través de una estructura que normalmente constituiría una barrera para tal paso.", "Creencia de que los acontecimientos, objetos o personas próximas del ambiente del sujeto tienen un sentido particular y no usual.", "Convicción de que el sujeto es atacado, acosado, engañado, perseguido o víctima de una conspiración.", "Convicción de que el sujeto ha perdido o perderá todas o casi todas sus posesiones materiales."]'::jsonb, 0, null, false),
('PIR 18', 'Pregunta 90', 'La ludopatía se encuadra en el epígrafe:', '["Trastorno disruptivo, del control de los impulsos y de la conducta no especificado (DSM 5).", "Trastorno obsesivo-compulsivo con predominio de actos compulsivos (rituales obsesivos) (CIE-10).", "Trastornos de los hábitos y del control de los impulsos (CIE-10).", "Trastorno relacionado con otras sustancias (o sustancias desconocidas) no especificado (DSM 5)."]'::jsonb, 2, null, false),
('PIR 18', 'Pregunta 91', '¿En cuál de los siguientes trastornos los síntomas son generados deliberadamente por el paciente?:', '["Trastorno de conversión.", "Trastorno de síntomas somáticos.", "Trastorno de ansiedad por enfermedad.", "Trastorno facticio."]'::jsonb, 3, null, false),
('PIR 18', 'Pregunta 92', 'En la tartamudez, cuando el espasmo se produce al iniciar el discurso, asociado a un bloqueo intenso que el sujeto vence por la fuerza, hablamos de:', '["Disfemia clónica.", "Disfemia tónica.", "Tartamudez secundaria.", "Taquifemia."]'::jsonb, 1, null, false),
('PIR 18', 'Pregunta 93', 'Para el diagnóstico del mutismo selectivo (DSM 5) ¿qué duración de la alteración se establece?:', '["Típicamente, seis o más meses.", "Al menos cuatro semanas en niños y adolescentes y típicamente seis o más meses en adultos.", "Mínimo de un mes (no limitada al primer mes de escuela).", "Mínimo de tres meses (no limitada al ámbito escolar o laboral)."]'::jsonb, 2, null, false),
('PIR 18', 'Pregunta 94', 'El síndrome amnésico se caracteriza por:', '["No tener una etiología orgánica.", "La pérdida de recuerdos autobiográficos, sin tener afectada la memoria anterógrada.", "No tener afectada la memoria operativa.", "Graves deficiencias en CI."]'::jsonb, 2, null, false),
('PIR 18', 'Pregunta 95', '¿Cuál de los siguientes trastornos psicológicos está incluido entre los que causan una mayor discapacidad a nivel mundial?:', '["Ezquizofrenia.", "Demencia.", "Trastornos de ansiedad.", "Depresión mayor (unipolar)."]'::jsonb, 3, null, false),
('PIR 18', 'Pregunta 96', 'La medicina psicosomática nació bajo la influencia de la escuela:', '["Psicodinámica.", "Conductista.", "Gestáltica.", "Cognitiva."]'::jsonb, 0, null, false),
('PIR 18', 'Pregunta 97', 'El diagnóstico del trastorno del insomnio se debe basar principalmente en (DSM 5):', '["La percepción subjetiva de la persona sobre el sueño o en la información de un cuidador.", "El resultado de una polisomnografía nocturna.", "Los datos de actigrafía.", "El resultado de un test de latencias múltiples de sueño."]'::jsonb, 0, null, false),
('PIR 18', 'Pregunta 98', 'En el síndrome de apnea e hipopnea obstructiva del sueño (DSM 5) en adultos, cada apnea o hipopnea representa una reducción en la respiración de al menos:', '["3 segundos de duración.", "5 segundos de duración.", "8 segundos de duración.", "10 segundos de duración."]'::jsonb, 3, null, false),
('PIR 18', 'Pregunta 99', 'En los individuos con trastorno del sueño relacionado con la respiración, la polisomnografía nocturna puede mostrar:', '["Aumento de la fase 1 del sueño y aumento de la fase REM y de las fases de ondas lentas.", "Disminución de la fase 1 del sueño y aumento de la fase REM y de las fases de ondas lentas.", "Aumento de la fase 1 del sueño y disminución de la fase REM y de las fases de ondas lentas.", "Ausencia de las fases 1 y 2 del sueño y disminución de la fase REM y de las fases de ondas lentas."]'::jsonb, 2, null, false),
('PIR 18', 'Pregunta 100', 'El trastorno del comportamiento del sueño REM:', '["Presenta la misma frecuencia en hombres que en mujeres.", "Es más frecuente en los varones.", "Es más frecuente en las mujeres.", "Es más frecuente en los niños."]'::jsonb, 1, null, false),
('PIR 18', 'Pregunta 101', 'La aparición de un periodo de movimientos oculares rápidos (MOR) durante los primeros minutos del sueño nocturno se suele considerar habitualmente como un signo de:', '["El síndrome de Pickwick.", "El síndrome de Kleine-Levin.", "Narcolepsia.", "Mioclonus nocturno."]'::jsonb, 2, null, false),
('PIR 18', 'Pregunta 102', 'Con relación a los aspectos relacionados con la cultura en el caso de la anorexia nerviosa (DSM 5), señale la respuesta CORRECTA:', '["No hay variaciones culturales en cuanto a su existencia y presentación.", "En la mayoría de los países de rentas medias y bajas se desconoce la incidencia de anorexia nerviosa.", "La preocupación por el peso en la anorexia nerviosa no varía entre contextos culturales.", "Los factores culturales no resultan relevantes con respecto a la anorexia nerviosa."]'::jsonb, 1, null, false),
('PIR 18', 'Pregunta 103', '¿Cuál de las siguientes respuestas considera correcta con respecto de los Trastornos de la Conducta Alimentaria?:', '["La presencia de obesidad o sobrepeso en la infancia puede aumentar el riesgo de bulimia nerviosa.", "La gravedad de la comorbilidad psicopatológica en la bulimia nerviosa no correlaciona con el pronóstico final de la misma.", "A día de hoy no se conocen anomalías cerebrales en la anorexia nerviosa.", "Los rasgos obsesivos observados en la infancia no aumentan el riesgo de padecer anorexia nerviosa."]'::jsonb, 0, null, false),
('PIR 18', 'Pregunta 104', 'En la bulimia nerviosa:', '["La sintomatología es vivida egosintónicamente.", "Sentimientos positivos y negativos, por igual, suelen desencadenar los atracones.", "Los atracones suelen producirse a escondidas o lo más discretamente posible.", "Los atracones siempre son de alimentos ricos en hidratos de carbono."]'::jsonb, 2, null, false),
('PIR 18', 'Pregunta 105', 'La presencia de miedo intenso a ganar peso, realización de una dieta muy restrictiva, ejercicio físico excesivo y vómitos autoinducidos en un chico de 18 años con un índice de Masa Corporal de 15,3 sugiere (DSM 5):', '["Anorexia nerviosa, tipo con atracones/purgas o tipo purgativo.", "Anorexia nerviosa atípica.", "Bulimia nerviosa.", "Anorexia nerviosa, tipo restrictivo."]'::jsonb, 0, null, false),
('PIR 18', 'Pregunta 106', 'El diagnóstico de trastorno ciclotímico (DSM 5), requiere:', '["Numerosos episodios hipomaníacos.", "Numerosos periodos de síntomas hipomaniacos.", "Numerosos episodios depresivos mayores.", "Numerosos síntomas esquizoafectivos."]'::jsonb, 1, null, false),
('PIR 18', 'Pregunta 107', 'Respecto del trastorno de dolor genitopélvico/penetración (DSM 5), señale la opción CORRECTA:', '["Puede consistir en miedo o ansiedad intensos ante la expectativa de sufrir dolor vulvovaginal o pélvico antes, durante o como resultado de la penetración vaginal.", "Hace referencia, exclusivamente, al dolor durante la penetración vaginal durante el coito.", "Pueden explicarse adecuadamente como consecuencia de la violencia de género.", "Su diagnóstico requiere que se produzca una tensión o contracción interna de los músculos del suelo pélvico durante el intento de penetración vaginal."]'::jsonb, 0, null, false),
('PIR 18', 'Pregunta 108', 'Los individuos con trastorno de fetichismo pueden referir excitación sexual intensa y recurrente:', '["Por el empleo de objetos inanimados o partes del cuerpo no genitales.", "Por niños prepúberes (generalmente menores de 13 años).", "Exclusivamente por artículos de vestir femeninos utilizados para transvestirse.", "Exclusivamente por artículos diseñados específicamente para la estimulación táctil de los genitales (p.ej., vibrador)."]'::jsonb, 0, null, false),
('PIR 18', 'Pregunta 109', 'La necesidad de una dosis mayor de una droga para provocar el mismo efecto farmacodinámico que al comienzo de tomarla, se le denomina:', '["Tolerancia.", "Tolerancia cruzada.", "Dependencia cruzada.", "Síndrome de abstinencia."]'::jsonb, 0, null, false),
('PIR 18', 'Pregunta 110', '¿Qué entendemos por potencial adictivo de una droga?:', '["La capacidad que tiene la droga de producir un sentimiento de satisfacción y bienestar psicológico.", "Un nivel de consumo muy alto de esa droga.", "La capacidad que tiene una sustancia psicoactiva de producir dependencia en aquellos que la consumen.", "La propensión a producir síndrome de abstinencia."]'::jsonb, 2, null, false),
('PIR 18', 'Pregunta 111', '¿Cuál es la droga que produce, en relación a otras drogas, un elevado grado de dependencia psicológica y poca dependencia física?:', '["El tabaco.", "Las drogas de síntesis.", "La cocaína.", "La heroína."]'::jsonb, 2, null, false),
('PIR 18', 'Pregunta 112', 'En el marco de las adicciones, los factores de riesgo distales descritos en la reconceptualización del modelo tradicional de prevención de recaídas de Marlatt (Hendershot et al. 2011) se refieren a:', '["Variables situaciones cambiantes.", "Predisposiciones estables que incrementan la vulnerabilidad individual a la caída.", "Precipitantes inmediatos que aumentan el riesgo de recaída.", "Precipitantes interoceptivos condicionados con el consumo de drogas."]'::jsonb, 1, null, false),
('PIR 18', 'Pregunta 113', 'Los pacientes con trastorno por dependencia del alcohol presentan frecuentemente:', '["Trastornos de la ansiedad.", "Esquizofrenia paranoide.", "Trastorno explosivo intermitente.", "Adicción a internet."]'::jsonb, 0, null, false),
('PIR 18', 'Pregunta 114', 'En un paciente que hace 15 días sufrió un grave accidente, presenta síntomas disociativos, malestar intenso y re-experimentación del suceso, ¿cuál de los siguientes diagnósticos iniciales sería más correcto?:', '["Trastorno de estrés agudo.", "Trastorno de estrés crónico.", "Trastorno de estrés post-traumático.", "Trastorno de estrés de inicio demorado."]'::jsonb, 0, null, false),
('PIR 18', 'Pregunta 115', '¿Cuál de los siguientes NO es un síntoma asociado al trastorno de ansiedad generalizada?:', '["Dolores de cabeza frecuentes.", "Sueño insatisfactorio.", "Falta de concentración.", "Facilidad para fatigarse."]'::jsonb, 0, null, false),
('PIR 18', 'Pregunta 116', '¿Cuál de los siguientes trastornos presenta, con frecuencia, comorbilidad con el trastorno de ansiedad generalizada? (DSM 5):', '["Los trastornos por consumo de sustancias.", "Los trastornos depresivos unipolares.", "Los trastornos de la conducta.", "Los trastornos neurocognitivos."]'::jsonb, 1, null, false),
('PIR 18', 'Pregunta 117', 'En un niño, la preocupación excesiva por la posibilidad de que sus padres sufran algún daño forma parte, más propiamente, del siguiente trastorno:', '["Fobia específica, entorno natural.", "Trastorno de ansiedad generalizada.", "Trastorno de ansiedad por separación.", "Síndrome de Munchausen por poderes."]'::jsonb, 2, null, false),
('PIR 18', 'Pregunta 118', '¿Cuál de los siguientes diagnósticos figura dentro del capítulo de los trastornos de ansiedad en el DSM 5?:', '["El trastorno obsesivo-compulsivo.", "La agorafobia.", "El trastorno de estrés postraumático.", "El trastorno de estrés agudo."]'::jsonb, 1, null, false),
('PIR 18', 'Pregunta 119', 'Una característica esencial para el diagnóstico del trastorno de ansiedad generalizada es, según el DSM 5, la:', '["Anticipación aprensiva.", "Sensibilidad a la ansiedad.", "Hipersomnia.", "Sentimiento de indefensión."]'::jsonb, 0, null, false),
('PIR 18', 'Pregunta 120', 'Dentro de las teorías cognitivo-conductuales, y respecto de la etiología de las fobias específicas, la formulación de Seligman sostiene que:', '["Las reacciones fóbicas se adquieren mediante condicionamiento y se mantienen mediante conductas de evitación al estímulo fóbico que reducen el miedo con éxito.", "Las reacciones fóbicas se adquieren por condicionamiento y se modulan por un mecanismo de \"preparación\" de la asociación.", "Los estilos de pensamiento distorsionados son mediadores de los trastornos fóbicos.", "El miedo fóbico es el resultado de la interacción de factores biológicos, psicológicos y sociales."]'::jsonb, 1, null, false),
('PIR 18', 'Pregunta 121', 'Según el DSM 5, en niños, el trastorno de ansiedad por separación muestra una especial comorbilidad con los siguientes trastornos:', '["Trastornos depresivos y bipolares.", "Trastorno obsesivo compulsivo y trastornos de personalidad.", "Trastornos de ansiedad social y fobia específica.", "Trastorno de ansiedad generalizada y fobia específica."]'::jsonb, 3, null, false),
('PIR 18', 'Pregunta 122', 'El principal núcleo sintomático de cara al diagnóstico del Trastorno de ansiedad generalizada (DSM 5) es de tipo:', '["Conductual (evitativo).", "Cognitivo (preocupación).", "Vegetativo (alteración respiratoria).", "Meta-cognitivo (atención selectiva a ciertas rumiaciones)."]'::jsonb, 1, null, false),
('PIR 18', 'Pregunta 123', 'La característica esencial de la agorafobia es:', '["La aparición de ansiedad cuando el individuo se encuentra en espacios abiertos o sin claras referencias o límites físicos.", "La aparición de ansiedad al encontrarse en lugares o situaciones donde escapar resulta embarazoso o en los que, en el caso de aparecer una crisis de angustia, no se dispone de ayuda.", "La aparición de ansiedad cuando han fracasado todos los comportamientos de evitación de los que dispone el individuo.", "La aparición de ansiedad nunca se dispara y/o exacerba en presencia de personas conocidas."]'::jsonb, 1, null, false),
('PIR 18', 'Pregunta 124', '¿Cuál de los siguientes síntomas aparece con más frecuencia durante un ataque de pánico?:', '["Dolor o molestias en el pecho.", "Molestias abdominales.", "Palpitaciones.", "Cefaleas"]'::jsonb, 2, null, false),
('PIR 18', 'Pregunta 125', '¿Qué característica diferencia al trastorno de ansiedad social respecto de la timidez?:', '["Menor impacto en las áreas sociales y laborales y en otras áreas importantes de funcionamiento.", "Una edad de comienzo más tardía.", "En general, es menos crónica.", "Tiene un menor grado de asociación con la evitación."]'::jsonb, 1, null, false),
('PIR 18', 'Pregunta 126', 'Los estudios que han comparado el lenguaje en la depresión y en la manía ponen de relieve que:', '["El discurso maniaco tiende a ser más vago y abstracto.", "El discurso depresivo se interesa más por las cosas que por las personas.", "El discurso maníaco emplea más referencias a sí mismo.", "El discurso está influenciado por las diferencias individuales, de forma que no se puede hablar de un patrón lingüístico típico que caracterice a cada uno de estos trastornos."]'::jsonb, 3, null, false),
('PIR 18', 'Pregunta 127', 'En general, para las teorías psicoanalíticas de la depresión, el síntoma clave de la depresión es:', '["La ira internalizada.", "La baja autoestima.", "La desesperanza.", "Las actitudes disfuncionales."]'::jsonb, 1, null, false),
('PIR 18', 'Pregunta 128', '¿Qué duración mínima han de tener los síntomas para que se cumplan los criterios de un episodio maniaco según el DSM 5?:', '["Una semana.", "Dos semanas.", "Un mes.", "Tres meses."]'::jsonb, 0, null, false),
('PIR 18', 'Pregunta 129', 'Según la Teoría de los Estilos de Respuesta (Nolen-Hoeksema) ¿qué forma de respuesta ante los primeros síntomas depresivos lleva a un incremento de la intensidad y duración de esos síntomas?:', '["La distracción.", "El estilo rumiativo.", "El realismo depresivo.", "La triada cognitiva."]'::jsonb, 1, null, false),
('PIR 18', 'Pregunta 130', '¿Cuál de los siguientes criterios debe estar presente necesariamente para el diagnóstico de episodio depresivo mayor?:', '["Insomnio.", "Problemas para la toma de decisiones.", "Estado de ánimo deprimido o pérdida de interés o de placer.", "Sentimientos excesivos de inutilidad o culpa."]'::jsonb, 2, null, false),
('PIR 18', 'Pregunta 131', 'El protocolo unificado para el tratamiento transdiagnóstico de los trastornos emocionales de Barlow, señale la INCORRECTA:', '["Tiene como objetivo exclusivamente el tratamiento de los trastornos de ansiedad.", "Incluye técnicas de reestructuración cognitiva.", "Incluye técnicas de Mindfulness.", "Proporciona un manual para terapeutas y otro para pacientes."]'::jsonb, 0, null, false),
('PIR 18', 'Pregunta 132', 'Según el DSM 5 ¿cuál de los siguientes trastornos de la personalidad se encuentra incluido en el grupo B?:', '["Trastorno de la personalidad histriónica.", "Trastorno de la personalidad esquizoide.", "Trastorno de la personalidad por evitación.", "Trastorno de la personalidad obsesivo-compulsivo."]'::jsonb, 0, null, false),
('PIR 18', 'Pregunta 133', 'Respecto del trastorno de personalidad límite, el diagnóstico diferencial debe hacerse principalmente con:', '["Trastornos de la ansiedad.", "Trastornos del estado de ánimo.", "Trastorno de la personalidad por evitación.", "Trastorno de la personalidad esquizoide."]'::jsonb, 1, null, false),
('PIR 18', 'Pregunta 134', 'El trastorno de la personalidad por evitación se caracteriza por (DSM 5):', '["Un patrón profundo de desapego social y un rango limitado de expresión emocional en situaciones interpersonales.", "Un patrón general de inestabilidad en las relaciones interpersonales, en la imagen de sí mismo y en la efectividad y la presencia de una notable impulsividad.", "Un patrón profundo de déficit sociales e interpersonales caracterizado por un malestar agudo y una capacidad reducida para las relaciones interpersonales.", "Un patrón general de inhibición, hipersensibilidad a la evaluación negativa y sentimientos de inferioridad."]'::jsonb, 3, null, false),
('PIR 18', 'Pregunta 135', '¿Cuál de las siguientes características indicaría un buen pronóstico para el trastorno psicótico breve?:', '["Pobre adaptación premórbida.", "Inicio progresivo de los síntomas.", "Síntomas afectivos.", "Desencadenantes leves."]'::jsonb, 2, null, false),
('PIR 18', 'Pregunta 136', 'Las personas que padecen esquizofrenia, en comparación con el resto de la población:', '["Tienen un tiempo de reacción (TR) más rápido.", "Tienen un tiempo de reacción (TR) más lento.", "Se benefician, en mayor medida, de los intervalos preparatorios (IP) en tareas de tiempo de reacción (TR).", "No difieren del resto de la población en tareas de tiempo de reacción (tareas simples)."]'::jsonb, 1, null, false),
('PIR 18', 'Pregunta 137', 'Señale cuál de los siguientes aspectos relacionados con el estilo y la actitud que adopta el terapeuta en la Terapia racional emotivo conductual (TREC) (Ellis, 1981; Ellis y Grieger, 1990) resulta más impropio de la TREC:', '["Ser muy activo verbalmente.", "No fomentar la catarsis.", "Ser flexible.", "La \"no-directividad\"."]'::jsonb, 3, null, false),
('PIR 18', 'Pregunta 138', 'Señale cuál de los siguientes componentes NO forma parte de la Terapia Cognitivo Conductual Focalizada en el Trauma (TF-CBT) para el tratamiento de los pacientes que han sufrido maltrato infantil:', '["Narrativa traumática.", "Desensibilización sistemática en imaginación.", "Relajación.", "Sesiones conjuntas padres e hijos."]'::jsonb, 1, null, false),
('PIR 18', 'Pregunta 139', 'Señale el trastorno de personalidad en el que las ideas paranoides NO aparecen como posible criterio de diagnóstico (DSM 5):', '["Límite.", "Esquizoide.", "Esquizotípico.", "Paranoide."]'::jsonb, 1, null, false),
('PIR 18', 'Pregunta 140', 'Señale cuál de los siguientes trastornos de personalidad cuenta con tratamientos más avalados por la investigación:', '["Obsesivo-compulsivo.", "Paranoide.", "Límite.", "Esquizotípico."]'::jsonb, 2, null, false),
('PIR 18', 'Pregunta 141', 'El diagnóstico de Trastorno adaptativo (DSM 5) exige que:', '["Los síntomas aparezcan después de 3 meses del inicio del factor estresante.", "La duración de los síntomas no sea inferior a 6 meses.", "Los síntomas no perduren más de 6 meses una vez finalice el factor estresante o sus consecuencias.", "Los síntomas aparezcan casi todos los días, existiendo más días con síntomas que sin ellos."]'::jsonb, 2, null, false),
('PIR 18', 'Pregunta 142', 'Señale cuál de las siguientes opciones recoge los síntomas que, en general, resultan nucleares (por ser similares) tanto en las personas con adicciones a sustancias como en las personas afectadas de las así denominadas "nuevas adicciones" conductuales:', '["Dependencia psicológica y tolerancia, pero no abstinencia.", "Dependencia psicológica, tolerancia y abstinencia.", "Tolerancia y abstinencia, pero no dependencia psicológica.", "Dependencia psicológica y abstinencia, pero no tolerancia."]'::jsonb, 1, null, false),
('PIR 18', 'Pregunta 143', 'El trastorno esquizoide de la personalidad (DSM 5) se caracteriza principalmente por:', '["Sospechas y desconfianzas profundas e infundadas hacia los demás.", "Un patrón consciente de desconsideración y violación de los derechos de los demás.", "Un patrón profundo de desapego social y un rango limitado de expresión emocional en situaciones interpersonales.", "Un patrón general de inestabilidad en las relaciones interpersonales y la presencia de una notable impulsividad."]'::jsonb, 2, null, false),
('PIR 18', 'Pregunta 144', 'La tricotilomanía:', '["No plantea problemas de diagnóstico diferencial con enfermedades dermatológicas.", "Muestra tasas de comorbilidad altas con el abuso de sustancias.", "Es más frecuente en la población adulta que en la infancia.", "Cuando se presenta de forma tardía, en la edad adulta, tiene mejor pronóstico que cuando aparece en la infancia."]'::jsonb, 1, null, false),
('PIR 18', 'Pregunta 145', 'Señale en cuál de las siguientes intervenciones, El Mindfulness tiene un papel menos relevante:', '["Terapia de aceptación y compromiso.", "Terapia de activación conductual.", "Terapia comportamental dialéctica (o dialéctico conductual)", "Terapia cognitiva basada en Mindfulness para la depresión."]'::jsonb, 1, null, false),
('PIR 18', 'Pregunta 146', 'En el contexto de la Terapia de aceptación y compromiso (ACT) y para explicar sus fundamentos, se utiliza la metáfora de un edificio. Dicho edificio metafórico tendría tres plantas. Debajo de todo ello, habría además unos cimientos (donde se encontraría el paradigma filosófico de base). Señale cuál de las siguientes opciones hace referencia a dichos cimientos:', '["La Teoría de los marcos relacionales.", "El Análisis conductual aplicado.", "El Análisis funcional de la conducta.", "El Contextualismo funcional."]'::jsonb, 3, null, false),
('PIR 18', 'Pregunta 147', 'En las así denominadas "adicciones hiperfágicas", NO constituye una de las características fundamentales (Alonso-Fernández, 2003):', '["La ingesta voraz.", "Comer grandes cantidades de alimento cuando se tiene hambre física.", "Continuar comiendo hasta sentir una sensación de plenitud desagradable.", "Sentirse culpable y/o desolado tras la sobreingesta."]'::jsonb, 1, null, false),
('PIR 18', 'Pregunta 148', 'Respecto de los menores afectados psicológicamente por haber sido abusados sexualmente, cabe afirmar lo siguiente:', '["La terapia cognitivo conductual focalizada en el trauma (TF-CBT) consigue efectos semejantes a la terapia de apoyo no directiva.", "La intervención con terapia cognitivo conductual focalizada en el trauma (TF-CBT) reduce síntomas pero no proporciona recursos y capacidades personales.", "La evidencia actual muestra que las prácticas de atención plena están contraindicadas.", "La sensación de \"salir del cuerpo\" o no sentir partes del mismo constituyen formas de disociación en estos pacientes."]'::jsonb, 3, null, false),
('PIR 18', 'Pregunta 149', 'El paquete terapéutico de Fairburn para la bulimia incluye tres fases. Identifique la que NO pertenece al mismo:', '["Trabajo en imaginación para la aceptación de la imagen corporal.", "Presentación del modelo cognitivo de mantenimiento de la bulimia.", "Establecimiento y mantenimiento de hábitos de alimentación saludable.", "Asentamiento de cambios y prevención de recaídas."]'::jsonb, 0, null, false),
('PIR 18', 'Pregunta 150', '¿Qué clase de fármaco es la quetiapina?:', '["Un benzodiacepina.", "Un ansiolítico.", "Un antidepresivo.", "Un antipsicótico."]'::jsonb, 3, null, false),
('PIR 18', 'Pregunta 151', 'En el marco de la Terapia Cognitiva de Ehlers y Clark (2000) para el trastorno de estrés postraumático, señale cuál de los siguientes no constituye un objetivo para dicha terapia:', '["Modificar la interpretación negativa del trauma.", "Modificar las conductas disfuncionales.", "Integrar los recuerdos traumáticos.", "Reemplazar las pesadillas relacionadas con el trauma por sueños más benignos."]'::jsonb, 3, null, false),
('PIR 18', 'Pregunta 152', 'Señale la opción INCORRECTA en el marco de la Terapia de Procesamiento Cognitivo de Resick y Schnicke (1993) para el trastorno de estrés postraumático:', '["Utiliza la exposición al trauma a través de la escritura y lectura de la experiencia traumática.", "Tiene como objetivo principal la habituación del miedo ante el recuerdo traumático.", "Pretende modificar los esquemas cognitivos desadaptativos y las emociones secundarias como culpa y desesperanza.", "Se focaliza mayoritariamente en el momento presente y no en la experiencia pasada."]'::jsonb, 1, null, false),
('PIR 18', 'Pregunta 153', '¿Cuál de las siguientes opciones es correcta respecto de la exposición en vivo como tratamiento para la agorafobia?:', '["Durante las sesiones de exposición es contraproducente que el paciente abandone la situación temporalmente.", "Para que sea realmente efectiva una tarea de exposición, la ansiedad debe bajar a cero Unidades Subjetivas de Ansiedad (USA).", "La frecuencia y la duración de las sesiones de exposición no influyen en la eficacia de la técnica.", "Aunque un familiar o el propio terapeuta acompañen al paciente en las primeras sesiones de exposición, la eficacia del tratamiento no se ve reducida."]'::jsonb, 3, null, false),
('PIR 18', 'Pregunta 154', 'El tratamiento del Control del Pánico (TCP) de Barlow se diferencia de la Terapia Cognitiva de Clark en que:', '["No incluye el componente cognitivo.", "Pone más énfasis en el componente de exposición interoceptiva.", "No incorpora un componente de relajación.", "Es un programa estructurado y está manualizado."]'::jsonb, 1, null, false),
('PIR 18', 'Pregunta 155', 'En el tratamiento de la fobia social, la Terapia Cognitivo-Conductual Comprensiva de Davidson et al. (2004) se diferencia de la terapia cognitivo-conductual en grupo de Heimberg et al. (1998) en que:', '["Se aplica en formato individual.", "No utiliza la exposición en vivo.", "Incluye un entrenamiento en habilidades sociales.", "No utiliza la reestructuración cognitiva."]'::jsonb, 2, null, false),
('PIR 18', 'Pregunta 156', 'En el programa de tratamiento cognitivo-conductual para la fobia social de Heimberg et al (1998):', '["Se empieza tratando los aspectos cognitivos y posteriormente se introduce la exposición progresiva.", "Se incluye un módulo específico de entrenamiento en habilidades sociales.", "Se basa principalmente en los aspectos conductuales y no introduce técnicas cognitivas.", "Las sesiones grupales tienen una duración de 1 hora."]'::jsonb, 0, null, false),
('PIR 18', 'Pregunta 157', 'Según el modelo conductual de Lewinsohn, la depresión se caracteriza fundamentalmente por:', '["Una baja tasa de reforzamiento positivo, en general.", "Una baja tasa de reforzamiento positivo contingente con la conducta.", "Una alta tasa de reforzamiento negativo.", "Un déficit en el repertorio conductual de la persona."]'::jsonb, 1, null, false),
('PIR 18', 'Pregunta 158', 'En la terapia cognitivo-conductual para las psicosis "la fijación de objetivos o agenda" y "la identificación de factores que aumentan la ansiedad o la desorganización del pensamiento", tiene como finalidad:', '["Modificar los esquemas cognitivos.", "Construir habilidades para prevenir recaídas.", "Mejorar la adherencia al tratamiento.", "Abordar los problemas de concentración."]'::jsonb, 3, null, false),
('PIR 18', 'Pregunta 159', 'Dentro de la terapia cognitiva para la esquizofrenia de Chadwick, Birchwood y Trower (1996) la intervención cognitiva que se aplica junto con el desafío verbal es:', '["La focalización en las alucinaciones.", "La normalización.", "La prueba de realidad.", "La reducción del estigma."]'::jsonb, 2, null, false),
('PIR 18', 'Pregunta 160', '¿Qué programa de intervención familiar en esquizofrenia tiene, entre sus objetivos principales, reducir la emoción expresada y aumentar las redes sociales de la familia?:', '["Paquete de intervenciones sociofamiliares de Leff.", "Terapia familiar conductual de Fallon.", "Terapia cognitivo-conductual de Tarrier.", "Modelo psicoeducativo de Anderson."]'::jsonb, 0, null, false),
('PIR 18', 'Pregunta 161', 'Dentro de las técnicas que promueven la focalización en las alucinaciones (Bentall y cols.) se recomienda en la primera fase del procedimiento de intervención solicitar al paciente que dirija su atención:', '["A las creencias y pensamientos respecto de las voces.", "Al contenido de las voces.", "A la forma y características físicas de las voces.", "A los sentimientos que le generan las voces."]'::jsonb, 2, null, false),
('PIR 18', 'Pregunta 162', 'Con la finalidad de mejorar la generalización y transferencia de las habilidades adquiridas en la terapia a la vida cotidiana, la Terapia Psicológica Integrada de la esquizofrenia (Roder y cols.) ha incorporado el módulo de:', '["Entrenamiento en habilidades de ocio, de vivienda y laborales.", "Entrenamiento en habilidades sociales y comunicativas.", "Solución de problemas interpersonales y resolución de conflictos.", "Comunicación verbal."]'::jsonb, 0, null, false),
('PIR 18', 'Pregunta 163', 'En el tratamiento farmacológico de la esquizofrenia ¿cuál de los siguientes fármacos, según su nombre genérico, es considerado un antipsicótico atípico?:', '["Clozapina.", "Clorpromazina.", "Haloperidol.", "Zuclopentixol."]'::jsonb, 0, null, false),
('PIR 18', 'Pregunta 164', 'El objetivo de la terapia cognitiva para el trastorno obsesivo-compulsivo es:', '["La exposición a los estímulos que provocan las obsesiones.", "Debatir con el paciente sobre la irracionalidad de las obsesiones.", "Debatir con el paciente sobre el contenido de sus obsesiones.", "Modificar las \"valoraciones disfuncionales\" que el paciente hace de sus obsesiones."]'::jsonb, 3, null, false),
('PIR 18', 'Pregunta 165', 'A un paciente diagnosticado de trastorno obsesivo-compulsivo con pensamiento mágico, en primer lugar, le indicamos que realice una predicción de cómo su pensamiento puede producir acontecimientos reales. A continuación le solicitamos que a lo largo de la próxima semana piense 80 veces al día que su microondas se va a estropear y otras 80 veces que le va a tocar la lotería. Finalmente, le pedimos que compare lo que ocurre con su predicción. ¿Qué técnica estamos utilizando?:', '["Realizando un experimento conductual.", "Solicitando que realice un ejercicio de auto-exposición.", "Empleando la técnica de la \"flecha descendente\" o del \"¿y qué?\".", "Empleando la distracción para disminuir sus obsesiones."]'::jsonb, 0, null, false),
('PIR 18', 'Pregunta 166', 'El programa PIENSA (Programa de Intervención en Psicosis Adolescente) tiene un carácter:', '["Psicodinámico.", "Cognitivo.", "Interpersonal.", "Psicoeducativo."]'::jsonb, 3, null, false),
('PIR 18', 'Pregunta 167', 'En el tratamiento del alcoholismo, los fármacos aversivos (disulfiram y cianamida cálcica) provocan una reacción aversiva a consecuencia de:', '["La inhibición de la enzima alcohol-deshidrogenasa.", "La inhibición de la enzima aldehído-deshidrogenasa.", "La interacción con los efectos del alcohol.", "La potenciación de los efectos del alcohol."]'::jsonb, 1, null, false),
('PIR 18', 'Pregunta 168', '¿Cuál de los siguientes tratamientos aversivos de tabaquismo tiene efectos más desagradables e intensos?:', '["La técnica de retención de humo.", "Saciación.", "Incremento del consumo habitual al doble de cigarrillos.", "La técnica de fumar rápido."]'::jsonb, 3, null, false),
('PIR 18', 'Pregunta 169', '¿Cuál es el tratamiento aconsejado en mujeres embarazadas con trastorno por consumo de heroína?:', '["Antagonistas, como la naltrexona, para contrarrestar los efectos de la heroína.", "Agonistas, como la metadona, para evitar el riesgo de aborto o estrés fetal.", "Abstinencia absoluta, para evitar los efectos de la heroína en el feto.", "No es conveniente inicial el tratamiento hasta después del parto, en el momento en que ya se encuentre en condiciones de recibir tratamiento farmacológico y con agonistas opiáceos."]'::jsonb, 1, null, false),
('PIR 18', 'Pregunta 170', '¿Qué término se utiliza para describir las relaciones probabilísticas entre la conducta y los cambios ambientales que las siguen?:', '["Contigüidad.", "Análisis funcional.", "Contingencia.", "Refuerzo."]'::jsonb, 2, null, false),
('PIR 18', 'Pregunta 171', 'Un paciente refiere que al oír los sonidos de una máquina tragaperras su corazón empieza a acelerarse y siente un impulso que le lleva a jugar hasta quedarse sin nada ¿Qué tipo de técnicas han mostrado ser más efectivas para este tipo de problemas?:', '["Técnicas de exposición con prevención de respuesta.", "Técnicas de consciencia plena (mindfulness).", "Técnicas de reversión del hábito.", "Técnicas de focalización sensorial."]'::jsonb, 0, null, false),
('PIR 18', 'Pregunta 172', '¿Qué aconsejaríamos a un paciente con agorafobia que durante una sesión de exposición en vivo nos comunica que se siente mal, que cree que se va a desmayar y que necesita abandonar la sesión?:', '["Suspender la sesión e intentarlo de nuevo el día próximo.", "Abandonar momentáneamente, no alejarse del lugar, y reanudar la sesión de inmediato.", "Utilizar técnicas de distracción o de imaginación encubierta para que se relaje y finalizar la sesión.", "No abandonar la sesión de ninguna manera para no entorpecer el proceso de habituación."]'::jsonb, 1, null, false),
('PIR 18', 'Pregunta 173', 'La técnica de desensibilización sistemática automatizada ¿en qué consiste?:', '["En realizar una grabación del audio de las sesiones para que el paciente pueda practicar en casa.", "Ayudar al cliente a imaginar las escenas de forma más vivida mediante las técnicas de realidad virtual.", "Utilizar los movimientos sacádicos de los ojos como respuesta incompatible.", "Utilizar la sugestión para aumentar el efecto de desensibilización."]'::jsonb, 0, null, false),
('PIR 18', 'Pregunta 174', 'Señale a qué grupo pertenecen la práctica de ejercicios cardiovasculares, la hiperventilación y las inhalaciones de dióxido de carbono:', '["Técnicas para el entrenamiento en biofeedback.", "Técnicas para facilitar la exposición interoceptiva.", "Técnicas para regular la activación fisiológica.", "Procedimientos de activación conductual."]'::jsonb, 1, null, false),
('PIR 18', 'Pregunta 175', 'Señale la respuesta correcta respecto al uso de la hipnosis en la Terapia Cognitivo-conductual:', '["La respuesta hipnótica facilita la comprensión de la actividad no consciente que depende del hemisferio izquierdo.", "Los actos hipnóticos se entienden como automáticos e involuntarios.", "Las respuestas obtenidas son actos del paciente que dependen de la autosugestión y no del poder del terapeuta.", "La eficacia de la hipnosis dependerá de la capacidad del paciente para alcanzar estados alterados de conciencia."]'::jsonb, 2, null, false),
('PIR 18', 'Pregunta 176', 'El término neutralización sirve para definir cualquier acto que pueda enmendar, reparar, corregir o restaurar los efectos emocionales perniciosos de un pensamiento obsesivo. Señale cuál de las siguientes afirmaciones sobre la neutralización es CORRECTA:', '["Es un componente de la técnica analítico funcional.", "Es un componente de la técnica de intención paradójica.", "Es un elemento potenciador de la exposición con prevención de respuesta.", "Es un elemento que debe ser evitado en la exposición con prevención de respuesta."]'::jsonb, 3, null, false),
('PIR 18', 'Pregunta 177', '¿En qué consiste la técnica operante llamada práctica negativa?:', '["Retirada de un reforzador de forma contingente con la emisión de una conducta que se desea eliminar.", "Presentación repetida de un estímulo reforzador hasta que el estímulo pierde su valor reforzante.", "Repetición reiterada de una conducta hasta que la realización resulta desagradable.", "Retirada de un reforzador de forma contingente con la emisión de una conducta negativa."]'::jsonb, 2, null, false),
('PIR 18', 'Pregunta 178', 'Según la Terapia Cognitiva basada en Mindfulness para la depresión (Segal y cols.); aquellas personas que ponen más empeño en mantener los pensamientos negativos fuera de la mente:', '["Presentan una mayor resiliencia.", "Tienen más probabilidades de desarrollar depresión.", "Recurren a conductas compensatorias.", "Generan más resistencia a la intervención terapéutica."]'::jsonb, 1, null, false),
('PIR 18', 'Pregunta 179', 'Según la Terapia de Aceptación y Compromiso. La realización de esfuerzos poco saludables por huir de las emociones y evitarlas se denomina:', '["Evitación positiva.", "Evitación negativa.", "Evitación experiencial.", "Evitación funcional."]'::jsonb, 2, null, false),
('PIR 18', 'Pregunta 180', 'En la terapia cognitiva de Beck, es recomendable añadir técnicas conductuales especialmente:', '["Al principio de la terapia y con pacientes más severamente deprimidos.", "Al final de la terapia para consolidar los cambios en los esquemas disfuncionales.", "Con los pacientes que presenten un BDI por debajo de 25, pero nunca con pacientes gravemente deprimidos.", "Cuando los pacientes tienen dificultades para identificar sus pensamientos automáticos."]'::jsonb, 0, null, false),
('PIR 18', 'Pregunta 181', 'La terapia interpersonal de Gerald. L. Klerman fue diseñada originalmente para:', '["El tratamiento agudo de la depresión mayor.", "El tratamiento de terapia de pareja en personas deprimidas.", "El tratamiento de mantenimiento para la depresión.", "El tratamiento del duelo (sin diagnóstico de depresión)."]'::jsonb, 2, null, false),
('PIR 18', 'Pregunta 182', 'La Terapia Interpersonal y del Ritmo Social (IPSRT), desarrollada por Frank et al. (1994), tiene como objetivos principales de tratamiento:', '["Los eventos vitales estresantes, los conflictos conyugales y el abandono de la psicoterapia.", "Los eventos vitales estresantes, las rupturas en los ritmos sociales y el no cumplimiento de la medicación.", "Los eventos vitales estresantes, las rupturas emocionales y el abandono de la psicoterapia.", "Los eventos vitales estresantes, las rupturas en los procesos psicosociales y el no cumplimiento de las recomendaciones psicoterapéuticas."]'::jsonb, 1, null, false),
('PIR 18', 'Pregunta 183', 'Dentro de las intervenciones para el tratamiento del trastorno bipolar, la que mayor consenso clínico y apoyo empírico preliminar presenta, es la:', '["Terapia familiar.", "Terapia cognitiva.", "Terapia interpersonal.", "Psicoeducación."]'::jsonb, 3, null, false),
('PIR 18', 'Pregunta 184', '¿En qué áreas problemáticas se centra la intervención de la Terapia Interpersonal para la Depresión?:', '["Duelo, disputas interpersonales, transición de rol y déficits interpersonales.", "Habilidades sociales, disputas interpersonales, transición de rol y déficits interpersonales.", "Duelo, habilidades sociales, déficits interpersonales y aislamiento social.", "Duelo, déficits interpersonales, aislamiento social y transición de rol."]'::jsonb, 0, null, false),
('PIR 18', 'Pregunta 185', '¿Cuál de los siguientes es un objetivo de los tratamientos psicológicos para el Trastorno Bipolar?:', '["Incrementar la adherencia al tratamiento farmacológico.", "Sustituir al tratamiento farmacológico.", "Preparar al paciente para la retirada del tratamiento farmacológico.", "Paliar los efectos secundarios del tratamiento farmacológico."]'::jsonb, 0, null, false),
('PIR 18', 'Pregunta 186', 'Señale la opción INCORRECTA respecto de la Terapia Cognitiva de la Depresión basada en la conciencia plena (mindfulness):', '["Está destinada a la prevención de recaídas en pacientes recuperados de algún episodio depresivo.", "Se trata de un programa psicoeducativo que se aplica en grupos.", "Busca el reconocimiento y la aceptación consciente de sentimientos y pensamientos depresógenos.", "Se centra en la modificación del contenido de los pensamientos depresivos."]'::jsonb, 3, null, false),
('PIR 18', 'Pregunta 187', '¿Cuál de los siguientes niveles pertenece a los cuatro dominios de la Sistemática de la Personalidad (Magnavita, 2005, 2006)?:', '["Dominio Sociocultural-Familiar.", "Dominio Neuropsíquico-Molecular.", "Dominio Económico-Social.", "Dominio Sistémico-Intrapersonal."]'::jsonb, 0, null, false),
('PIR 18', 'Pregunta 188', 'Según las reglas de la formación de habilidades de la Terapia Dialéctica Conductual para el tratamiento del Trastorno Límite de la Personalidad ¿cuántas semanas seguidas sin acudir a terapia se considerarían necesarias para determinar que el cliente está excluido de la terapia?:', '["2 semanas.", "4 semanas.", "6 semanas.", "8 semanas."]'::jsonb, 1, null, false),
('PIR 18', 'Pregunta 189', 'El programa de intervención STEPPS (Systems Training for Emotional Predictability and Problem Solving) (Blum et al., 2008) para el tratamiento del Trastorno Límite de la Personalidad consta de tres componentes: 1) psicoeducación, 2) entrenamiento en habilidades para el manejo de las emociones y ¿cuál es el tercero?:', '["Entrenamiento en habilidades sociales.", "Entrenamiento en técnicas de mindfulness.", "Entrenamiento en flexibilidad cognitiva.", "Entrenamiento para el manejo de las conductas."]'::jsonb, 3, null, false),
('PIR 18', 'Pregunta 190', '¿Cuál de las siguientes habilidades correspondería a una habilidad de distracción según la Terapia Dialéctica Conductual?:', '["Ayudar a los demás.", "Practicar la relajación.", "Vivir el presente en cada momento.", "Practicar la aceptación radical."]'::jsonb, 0, null, false),
('PIR 18', 'Pregunta 191', '¿Cuál es la estrategia primordial en el tratamiento cognitivo (Beck y Freeman et al.) del trastorno paranoide de la personalidad?:', '["Tratar de relajar la vigilancia y la posición defensiva del individuo.", "Tratar de modificar la conducta interpersonal.", "Tratar de aumentar el sentimiento de capacidad del individuo para enfrentarse a situaciones problemáticas.", "Tratar de modificar los supuestos básicos del individuo."]'::jsonb, 2, null, false),
('PIR 18', 'Pregunta 192', '¿Qué duración se suele recomendar para llevar a cabo una sesión de inundación?:', '["Entre 10 y 15 minutos.", "Entre 15 y 30 minutos.", "Entre 30 y 60 minutos.", "Entre 60 y 120 minutos."]'::jsonb, 3, null, false),
('PIR 18', 'Pregunta 193', '¿Qué autor incluye en su terapia someter a "prueba de realidad" los pensamientos, como estrategia terapéutica?:', '["A. T. Beck.", "A. Ellis.", "M. J. Mahoney.", "A. Bandura."]'::jsonb, 0, null, false),
('PIR 18', 'Pregunta 194', '¿De cuántas fases se compone el entrenamiento en autoinstrucciones postulado por D. Meichenbaum?:', '["Cuatro.", "Cinco.", "Seis.", "Ocho."]'::jsonb, 1, null, false),
('PIR 18', 'Pregunta 195', 'La desensibilización por contacto, aparte de Desensibilización Sistemática ¿qué otra técnica incluye?:', '["El entrenamiento en autocontrol.", "La realidad virtual.", "El modelado.", "La inclusión de estímulos principalmente físicos."]'::jsonb, 2, null, false),
('PIR 18', 'Pregunta 196', '¿Qué forma de proceder sería la recomendable si se aplica el reforzamiento positivo encubierto?:', '["Conviene utilizar inicialmente un programa de razón variable para pasar posteriormente a uno de razón fija.", "Conviene utilizar inicialmente un programa de razón fija para pasar posteriormente a uno de razón variable.", "Conviene combinar intermitentemente e intercalar programas de razón fija y variable.", "Conviene utilizar inicialmente un programa intermitente para pasar posteriormente a uno continuo."]'::jsonb, 1, null, false),
('PIR 18', 'Pregunta 197', '¿En qué principio operante se basa el coste de respuesta encubierto?:', '["En el castigo negativo.", "En la extinción encubierta.", "En el reforzamiento negativo.", "En el desvanecimiento."]'::jsonb, 0, null, false),
('PIR 18', 'Pregunta 198', 'En el área de las nuevas tecnologías al servicio de la intervención psicológica ¿qué tecnología permite superponer objetos o elementos tridimensionales, generados a través del ordenador, sobre una escena real de tal manera que el usuario pueda visualizar ambas cosas a la vez?:', '["La realidad aumentada.", "La cibert erapia.", "La realidad virtual.", "La virtualidad aumentada."]'::jsonb, 0, null, false),
('PIR 18', 'Pregunta 199', '¿En qué fase de la Solución de Problemas (D''Zurilla y Goldfried) se anticipan las consecuencias o resultados de la decisión?:', '["En la Definición y formulación del problema.", "En la de Propuesta de alternativas.", "En la de Toma de decisiones.", "En la de Puesta en práctica y verificación de la solución."]'::jsonb, 2, null, false),
('PIR 18', 'Pregunta 200', '¿Qué modalidad de encadenamiento se suele emplear con mayor frecuencia?:', '["El encadenamiento hacia adelante.", "El encadenamiento inhibitorio.", "El encadenamiento de tarea completa.", "El encadenamiento hacia atrás."]'::jsonb, 3, null, false),
('PIR 18', 'Pregunta 201', '¿Cuál de los siguientes NO es uno de los cuatro temas básicos de la Terapia de Aceptación y Compromiso?:', '["Los valores.", "La exposición.", "Desactivación de funciones y el distanciamiento.", "Los valores contextuales-familiares."]'::jsonb, 3, null, false),
('PIR 18', 'Pregunta 202', '¿Al tratamiento de qué trastornos va dirigido el protocolo de terapia grupal cognitiva-conductual transdiagnóstica de P. J. Norton (2012)?:', '["Trastornos de ansiedad.", "Trastornos del estado de ánimo unipolares.", "Trastornos del estado de ánimo unipolares y trastorno bipolar.", "Trastorno límite de personalidad."]'::jsonb, 0, null, false),
('PIR 18', 'Pregunta 203', '¿Cómo se denomina la técnica operante que consiste en introducir sistemáticamente ayudas o instigadores para que el sujeto aprenda una conducta y posteriormente se procede a la retirada progresiva de dichas ayudas o instigadores:', '["Desvanecimiento.", "Encadenamiento hacia atrás.", "Moldeamiento.", "Modelamiento."]'::jsonb, 0, null, false),
('PIR 18', 'Pregunta 204', 'En el tratamiento del trastorno obsesivo-compulsivo a menudo se da información a los pacientes sobre los pensamientos intrusos u obsesiones no clínicas, que se describen como:', '["Pensamientos que nos hacen vulnerables a tener un trastorno obsesivo-compulsivo.", "Pensamientos experimentados por la población general, y similares en contenido a las obsesiones clínicas.", "Pensamientos que se recomienda evitar o suprimir cuando se experimentan.", "Pensamientos cuyo contenido debe ser rebatido una vez que se experimentan."]'::jsonb, 1, null, false),
('PIR 18', 'Pregunta 205', 'En el marco del modelo metacognitivo de Wells (2009) y por lo que respecta al Trastorno de ansiedad generalizada, se afirma que:', '["Las preocupaciones Tipo 1 se refieren a eventos externos o internos de tipo cognitivo.", "Las preocupaciones Tipo 2 llevan al paciente a prestar menos atención a los pensamientos no deseados y a una peor detección de los mismos.", "Las preocupaciones Tipo 2 llevan al paciente a poner en marcha conductas de seguridad dirigidas a encontrar tranquilización.", "El Tratamiento debe centrarse prioritariamente en el cuestionamiento de las preocupaciones sobre eventos externos o internos no cognitivos."]'::jsonb, 2, null, false),
('PIR 18', 'Pregunta 206', '¿Qué programa de tratamiento para el trastorno de ansiedad por enfermedad/ hipocondría se presenta como un curso que permitirá aprender sobre la percepción de los síntomas físicos?:', '["El programa propuesto desde la Psicología del \"self\" de Diamond.", "El tratamiento del estilo somático amplificador de Barsky.", "El tratamiento de las interpretaciones catastrofistas de Warwick y Salkovskis.", "El tratamiento cognitivo de Kellner."]'::jsonb, 1, null, false),
('PIR 18', 'Pregunta 207', '¿Qué diagnostico (DSM 5) sugieren los siguientes síntomas en un adolescente de 16 años?: Patrón repetitivo y persistente de comportamiento en el que no se respetan los derechos de otros, las normas o reglas sociales propias de la edad, lo que se manifiesta por la presencia en el último año de al menos 3 conductas en cualquiera de las siguientes categorías (agresión a personas y animales; destrucción de la propiedad; engaño o robo; incumplimiento grave de normas) existiendo al menos 1 en los últimos 6 meses:', '["Trastorno negativista desafiante.", "Trastorno explosivo intermitente.", "Trastorno de adaptación.", "Trastorno de conducta."]'::jsonb, 3, null, false),
('PIR 18', 'Pregunta 208', 'Según el DSM 5 cuál de las siguientes afirmaciones sobre la Enuresis NO es correcta:', '["El comportamiento es clínicamente significativo cuando se manifiesta con una frecuencia de, al menos, 2 veces por semana durante un mínimo de 6 meses.", "La edad cronológica del paciente es de, por lo menos, 5 años (o desarrollo equivalente).", "La prevalencia de la enuresis es de 3-5% en niños de 10 años.", "La enuresis nocturna es más frecuente en niños que en niñas."]'::jsonb, 0, null, false),
('PIR 18', 'Pregunta 209', 'En los individuos con trastorno de conducta de cualquier subtipo o nivel de gravedad ¿a qué se asocia con más frecuencia el especificador de diagnóstico denominado "con emociones prosociales limitadas" en niños y adolescentes (DSM 5)?:', '["A un trastorno de conducta que incluye actos de delincuencia.", "A un trastorno de conducta de inicio infantil y más grave.", "A un trastorno de conducta de inicio adolescente y más grave.", "A un trastorno de conducta y un trastorno de personalidad."]'::jsonb, 1, null, false),
('PIR 18', 'Pregunta 210', '¿En qué funciones son más evidentes los déficits atencionales de los niños con TDAH?:', '["De manera general en las redes atencionales de Posner.", "En la atención sostenida.", "En la orientación y selección atencional.", "En la atención dividida."]'::jsonb, 1, null, false),
('PIR 18', 'Pregunta 211', 'Según el DSM 5 ¿a qué edad tienen que estar presentes los síntomas de desatención e hiperactividad/impulsividad para poder hacer el diagnóstico de TDAH?:', '["Antes de los 7 años.", "Antes de los 5 años.", "No hay una edad concreta definida, pero en todo caso antes de los 18 años.", "Antes de los 12 años."]'::jsonb, 3, null, false),
('PIR 18', 'Pregunta 212', '¿Qué diferencia el trastorno explosivo intermitente (TEI) y el trastorno de desregulación disruptiva (o destructiva) del estado de ánimo (TDDEA)?:', '["Ambos pertenecen a la categoría de trastornos depresivos, pero en el caso del TEI se usa para niños menores de 7 años con preponderancia de un estado de ánimo irascible.", "En el TEI la duración de los síntomas es menor y además no hay presencia de estado de ánimo alterado entre los episodios.", "Ambos pertenecen a la categoría de disruptivos, del control de los impulsos y de la conducta, pero sólo en el caso del TDDEA se da presencia de síntomas depresivos.", "Suponen un continuo evolutivo: en la infancia se da el TEI que, si no es convenientemente tratado, desemboca habitualmente en el TDDEA."]'::jsonb, 1, null, false),
('PIR 18', 'Pregunta 213', '¿Cuál es el principal motivo por el que se añade en el DSM 5 el diagnóstico por trastorno de desregulación disruptiva (o destructiva) del estado de ánimo?:', '["Para diferenciar el trastorno depresivo en adultos y en niños.", "Para enlazar los trastornos del estado de ánimo con el trastorno por déficit de atención e hiperactividad en niños.", "Para destacar la presencia de conductas problemas en el trastorno depresivo en la infancia.", "Para evitar el excesivo diagnóstico del trastorno bipolar en niños."]'::jsonb, 3, null, false),
('PIR 18', 'Pregunta 214', '¿El programa de tratamiento PECS (Sistema de Comunicación por Intercambio de Imágenes) ha sido creado para individuos afectados de?:', '["TDAH.", "Trastornos de depresión.", "Autismo.", "Trastorno de habilidades sociales."]'::jsonb, 2, null, false),
('PIR 18', 'Pregunta 215', '¿Cuáles son las evidencias empíricas sobre la eficacia del método de la alarma para tratar la enuresis nocturna en la infancia?:', '["La alarma ante la orina es un procedimiento bien establecido experimentalmente y ha demostrado ser más eficaz que el entrenamiento en retención, la psicoterapia o el no tratamiento.", "No existe evidencia sobre la efectividad del método de la alarma para curar la enuresis nocturna.", "La alarma antes o después de que se produzca la orina (o accidente) es un procedimiento bien establecido experimentalmente pero no ha demostrado ser más eficaz que el entrenamiento en retención.", "La utilización del método de alarma, aunque es efectivo, no se recomienda, al ser un método aversivo, con efectos psicológicos secundarios."]'::jsonb, 0, null, false),
('PIR 18', 'Pregunta 216', 'La práctica reforzada es considerada un tratamiento eficaz bien establecido en las fobias infantiles ¿en qué consiste?:', '["Consiste en aproximaciones sucesivas a los estímulos fóbicos en vivo (práctica), seguidas de reforzamiento positivo por parte del propio niño a través de autoinstrucciones y relajación como respuesta incompatible mientras se expone.", "Consiste en aproximaciones sucesivas a los estímulos fóbicos en vivo (práctica), seguidas de consecuencias positivas materiales o sociales (reforzamiento).", "Consiste en la repetición continua (practicar) de una respuesta de relajación o mindfulness ante los estímulos fóbicos, acompañada del reforzamiento por los adultos de las actitudes de valentía del niño.", "Consiste en la presentación de estímulos reforzantes positivos para el niño a la par que se dan los estímulos fóbicos, para que puedan competir motivacionalmente y el niño permanezca practicando la exposición a lo fóbico por el placer de los estímulos reforzantes."]'::jsonb, 1, null, false),
('PIR 18', 'Pregunta 217', 'En los trastornos por negativismo desafiante el tratamiento supone intervenir en paralelo con los padres y con los hijos. Los programas de entrenamiento de padres en este ámbito tienen como objetivo principal (p.e. Forehand y McMahon):', '["Mejorar las relaciones de los padres para que exista un clima de comprensión del niño y de sus emociones; así como hacerle sentir que es querido y está protegido.", "Que los niños aprendan las razones por las que los padres le ponen unas normas y límites a fin de que las interioricen.", "Cambiar actitudes parentales disfuncionales y negligentes en los padres tales como: establecer límite a la imaginación y juego de sus hijos, fomentar autonomía en aspectos del cuidado personal, o en el dormir solo, etc.", "Modificar pautas anómalas de interacción padres-hijos."]'::jsonb, 3, null, false),
('PIR 18', 'Pregunta 218', 'Uno de los programas de intervención "tradicionales" en niños con problemas de oposición, agresividad y negativismo es el propuesto por Kazdin. Consiste en lo siguiente:', '["Se entrenan habilidades cognitivas de resolución de problemas o conflictos a través de autoinstrucciones verbales.", "Se entrena al niño a llevar a cabo relajación y respiración emocional como estrategias de contención de la ira y el enfado.", "Se aplica al niño reestructuración cognitiva a fin de entender de donde le vienen las razones psicológicas de su enfado.", "Se entrena al niño a través de role-playing a adoptar un estilo de interacción con sus compañeros y sus familiares más empático y más flexible cognitiva y comportamentalmente."]'::jsonb, 0, null, false),
('PIR 18', 'Pregunta 219', 'Las imágenes emotivas se han mostrado como un tratamiento experimental para las fobias infantiles y consisten en:', '["Una forma de DS imaginada con todos los componentes propios pero con un tipo de respuesta incompatible más elaborada; en tanto que se utiliza una historia en la que participa el propio niño junto a un superhéroe o un personaje de ficción favorito.", "Una DS en imaginación de la que respuesta incompatible es la relajación y la jerarquía de estímulos fóbicos o temidos es acompañada de superhéroes del niño de mayor a menor preferencia.", "Un programa multicomponente, que entre otras estrategias contiene el que el niño ha de evocar imágenes de emociones positivas que son capaces de darle seguridad para enfrentarse a sus estímulos fóbicos.", "Una estrategia cognitiva por la que el niño ha de evocar a través de autoinstrucciones imágenes positivas incompatibles con otras que representan las situaciones temidas."]'::jsonb, 0, null, false),
('PIR 18', 'Pregunta 220', '¿El fármaco de primera elección en el tratamiento de la enuresis es?:', '["Imipramina.", "Amitriptilina.", "Desmopresina.", "Tiroxina."]'::jsonb, 2, null, false),
('PIR 18', 'Pregunta 221', 'Para el tratamiento farmacológico de TDHA en niños se recomienda preferentemente por su mayor eficacia:', '["Metilfenidato.", "Bupropión.", "Tricíclicos.", "ISRS."]'::jsonb, 0, null, false),
('PIR 18', 'Pregunta 222', 'Al respecto de las dietas, señale la afirmación CORRECTA:', '["Una sobrealimentación continua y progresiva conduce a un incremento de peso también continuo.", "Hay un punto a partir del cual para seguir perdiendo peso es necesario un incremento en la restricción calórica.", "Cuando las personas se someten a una dieta y pierden peso rápidamente, su metabolismo se acelera.", "El organismo humano tiene más facilidad para perder peso que para ganarlo."]'::jsonb, 1, null, false),
('PIR 18', 'Pregunta 223', 'Según el modelo operante del dolor crónico (Fordyce, 1976) ¿qué variable facilita la cronificación del dolor?:', '["Los estímulos nociceptivos.", "Las contingencias ambientales.", "El sistema motivacional-cognitivo.", "El sistema discriminativo."]'::jsonb, 1, null, false),
('PIR 18', 'Pregunta 224', '¿Cuál de las siguientes variables pertenece a la Teoría de la acción razonada de Fishbein y Ajzen (1975)?:', '["El conocimiento implícito.", "La percepción de gravedad.", "La intención de conducta.", "La autoeficacia."]'::jsonb, 2, null, false),
('PIR 18', 'Pregunta 225', 'En situación de enfermedad ¿cuál de los siguientes factores facilitaría la adherencia terapéutica?:', '["La gravedad objetiva de la enfermedad.", "La experiencia subjetiva de gravedad de la enfermedad (p.e. dolor).", "La cronificación de la enfermedad.", "Ser menor de edad."]'::jsonb, 1, null, false),
('PIR 18', 'Pregunta 226', 'Señale cuál de los siguientes constituye un objetivo de prevención primaria en el marco de la psicología de la salud:', '["Prevenir recaídas en población con problemas de salud.", "Diagnosticar precozmente la existencia de una enfermedad.", "Favorecer la rehabilitación en enfermedades crónicas.", "Evitar la aparición de enfermedades en la población."]'::jsonb, 3, null, false),
('PIR 18', 'Pregunta 227', 'Cuando los adultos ayudan a los niños a realizar tareas cognitivas (p.e. hacer un puzzle o los deberes), van ajustando su nivel de apoyo en función la competencia que muestra el niño. Este ajuste, según Vygotsky, se denomina:', '["Motivación extrínseca.", "Andamiaje.", "Toma de control.", "Heterodireccion."]'::jsonb, 1, null, false),
('PIR 18', 'Pregunta 228', '¿Cuál de los siguientes enunciados describe una diferencia reconocida entre temperamento y personalidad?:', '["Los factores biológicos tienen un papel determinante en el temperamento, mientras que los factores ambientales lo tienen en la personalidad.", "El temperamento se manifiesta en la edad adulta, mientras que la personalidad se manifiesta al comienzo de la vida.", "El temperamento se refiere al contenido o propósito de la conducta, mientras que la personalidad describe las características energéticas, temporales y de estilo de la conducta.", "El temperamento es más modificable que la personalidad."]'::jsonb, 0, null, false),
('PIR 18', 'Pregunta 229', '¿Entre los más importantes indicios de reactividad como fuente de error en la observación NO se encuentra?:', '["El cambio sistemático de la frecuencia en la aparición de las conductas objeto de estudio.", "La disminución de la variabilidad de la conducta que no se relaciona con cambios en las condiciones ambientales.", "La expresión verbal de que se está produciendo reactividad.", "Las diferencias halladas entre lo observado y un criterio objetivo previamente conocido."]'::jsonb, 1, null, false),
('PIR 18', 'Pregunta 230', 'En evaluación psicológica, las diferencias entre lo observado y un criterio objetivo previamente conocido constituyen un indicio de una fuente de error:', '["Denominada \"reactividad\" (del sujeto observado).", "Asociada al entrenamiento del observador.", "Asociada a las expectativas del observador.", "Relacionada con el grado de patología del sujeto observado."]'::jsonb, 0, null, false),
('PIR 18', 'Pregunta 231', '¿Qué cuestionario para la evaluación de la depresión en la infancia se construyó a partir del Inventario de depresión para adultos de Beck?:', '["Inventario de depresión infantil (CDI).", "Escala de depresión para niños (CDS).", "Cuestionario estructural tetradimensional para la depresión en la infancia (CET-DEI).", "Escala de depresión para niños del Centro de Estudios Epidemiológicos (CES-D)."]'::jsonb, 0, null, false),
('PIR 18', 'Pregunta 232', 'Los síntomas depresivos característicos del Trastorno Disfórico Premenstrual se dan:', '["En cualquiera de las fases del ciclo menstrual.", "En los primeros días de la menstruación.", "En las semanas intermedias del ciclo menstrual.", "En la última semana del ciclo menstrual."]'::jsonb, 3, null, false),
('PIR 18', 'Pregunta 233', 'En el tratamiento cognitivo-conductual para la bulimia nerviosa de Fairburn ¿cuál es el objetivo principal de la segunda fase?:', '["Desarrollar conciencia y aceptación del problema.", "Prevenir las recaídas de la bulimia nerviosa.", "Modificar los pensamientos, creencias y valores disfuncionales que mantienen el problema.", "Potenciar el mantenimiento de las ganancias del tratamiento."]'::jsonb, 2, null, false),
('PIR 18', 'Pregunta 234', 'En el entrenamiento de los hábitos de la defecación y respecto a de las indicaciones relacionadas con que el niño se siente en el retrete después de la ingestión, señale la opción CORRECTA:', '["No debe indicarse que se siente más de 5 minutos.", "Se recomienda que se siente durante 10-20 minutos.", "Debe realizarse a elección del niño.", "Está contraindicado."]'::jsonb, 1, null, false),
('PIR 18', 'Pregunta 235', 'Según la clasificación internacional de los trastornos del sueño, 2ª edición de la American Academy of Sleep Medicine (AASM 2005), los trastornos del despertar (desde el sueño no REM) se clasifican como:', '["Insomnios.", "Trastorno del ritmo cardíaco.", "Parasomnia.", "Trastorno del sueño relacionado con la respiración."]'::jsonb, 2, null, false);
